  input  logic         dcache_wfi_wfiSafe,
  input  logic         uncache_wfi_wfiSafe,
  input  logic         lsq_wfi_wfiSafe,
  input  logic         ptw_wfi_wfiSafe,
  output logic         io_wfi_wfiSafe
);

  // ===========================================================================
  // §1 后端重定向打一拍；CSR 预取开关打拍；L2 hint 打一拍
  //   redirect = RegNextWithEnable(io.redirect)：valid 逐拍打（异步复位 0），内容只在 valid 时更新。
  //   向量访存例外（isVlsException）的重定向一律按 flushAfter（level=0）处理。
  // ===========================================================================
  always_ff @(posedge clock or posedge reset) begin
    if (reset) redirect_valid <= 1'b0;
    else       redirect_valid <= io_redirect_valid;
  end
  always_ff @(posedge clock) begin
    if (io_redirect_valid) begin
      redirect_robIdx_flag  <= io_redirect_bits_robIdx_flag;
      redirect_robIdx_value <= io_redirect_bits_robIdx_value;
      redirect_level        <= io_redirect_bits_level & ~io_redirect_bits_isVlsException;
    end
  end

  // 预取相关 CSR 开关：各打两拍（GatedRegNextN(x, 2, 复位值)），[0] 是第一拍、[1] 是送出去的那拍。
  logic       pf_l1d_enable [2];          // L1D 预取总开关
  logic       pf_sms_recv_enable [2];     // SMS（l2_pf_recv_enable）
  logic       pf_l1_stride_enable [2];    // L1 流预取的 stride 部分
  logic       pf_train_on_hit [2];        // 预取命中也训练 SMS（RegNextN，复位 1）
  always_ff @(posedge clock or posedge reset) begin
    if (reset) begin
      l2_pf_store_only <= 1'b0;
      for (int k = 0; k < 2; k++) begin
        pf_l1d_enable[k]        <= 1'b0;
        pf_sms_recv_enable[k]   <= 1'b0;
        pf_sms_agt_enable[k]    <= 1'b0;
        pf_sms_pht_enable[k]    <= 1'b0;
        pf_sms_act_threshold[k] <= 4'd12;
        pf_sms_act_stride[k]    <= 6'd30;
        pf_l1_stride_enable[k]  <= 1'b0;
        pf_train_on_hit[k]      <= 1'b1;
      end
    end else begin
      l2_pf_store_only        <= io_ooo_to_mem_csrCtrl_pf_ctrl_l2_pf_store_only;
      pf_l1d_enable[0]        <= io_ooo_to_mem_csrCtrl_pf_ctrl_l1D_pf_enable;
      pf_sms_recv_enable[0]   <= io_ooo_to_mem_csrCtrl_pf_ctrl_l2_pf_recv_enable;
      pf_sms_agt_enable[0]    <= io_ooo_to_mem_csrCtrl_pf_ctrl_l1D_pf_enable_agt;
      pf_sms_pht_enable[0]    <= io_ooo_to_mem_csrCtrl_pf_ctrl_l1D_pf_enable_pht;
      pf_sms_act_threshold[0] <= io_ooo_to_mem_csrCtrl_pf_ctrl_l1D_pf_active_threshold;
      pf_sms_act_stride[0]    <= io_ooo_to_mem_csrCtrl_pf_ctrl_l1D_pf_active_stride;
      pf_l1_stride_enable[0]  <= io_ooo_to_mem_csrCtrl_pf_ctrl_l1D_pf_enable_stride;
      pf_train_on_hit[0]      <= io_ooo_to_mem_csrCtrl_pf_ctrl_l1D_pf_train_on_hit;
      pf_l1d_enable[1]        <= pf_l1d_enable[0];
      pf_sms_recv_enable[1]   <= pf_sms_recv_enable[0];
      pf_sms_agt_enable[1]    <= pf_sms_agt_enable[0];
      pf_sms_pht_enable[1]    <= pf_sms_pht_enable[0];
      pf_sms_act_threshold[1] <= pf_sms_act_threshold[0];
      pf_sms_act_stride[1]    <= pf_sms_act_stride[0];
      pf_l1_stride_enable[1]  <= pf_l1_stride_enable[0];
      pf_train_on_hit[1]      <= pf_train_on_hit[0];
    end
  end
  // 两个预取器的使能 = 总开关 && 各自开关（Constantin 的 enableSMS / enableL1StreamPrefetcher 恒真）
  assign sms_enable  = pf_l1d_enable[1] & pf_sms_recv_enable[1];
  assign l1Pf_enable = pf_l1d_enable[1] & pf_l1_stride_enable[1];

  // L2 → L1 的 hint（"某个 MSHR 的回填马上到"）打一拍再给 DCache 与 LSQ
  always_ff @(posedge clock) begin
    l2hint_valid     <= io_l2_hint_valid;
    l2hint_sourceId  <= io_l2_hint_bits_sourceId;
    l2hint_isKeyword <= io_l2_hint_bits_isKeyword;
  end

  // ===========================================================================
  // §2 sfence 与 TLB CSR 各打两拍（RegNext(RegNext(...))，不复位）
  //   DTLB / L2TLB / PTWNewFilter / PMP 检查口看到的都是第二拍（*_d1 是中间一拍）。
  // ===========================================================================
  logic         sfence_d1_valid, sfence_d1_rs1, sfence_d1_rs2, sfence_d1_flushPipe, sfence_d1_hv, sfence_d1_hg;
  logic [49:0]  sfence_d1_addr;
  logic [15:0]  sfence_d1_id;
  always_ff @(posedge clock) begin
    sfence_d1_valid     <= io_ooo_to_mem_sfence_valid;
    sfence_d1_rs1       <= io_ooo_to_mem_sfence_bits_rs1;
    sfence_d1_rs2       <= io_ooo_to_mem_sfence_bits_rs2;
    sfence_d1_addr      <= io_ooo_to_mem_sfence_bits_addr;
    sfence_d1_id        <= io_ooo_to_mem_sfence_bits_id;
    sfence_d1_flushPipe <= io_ooo_to_mem_sfence_bits_flushPipe;
    sfence_d1_hv        <= io_ooo_to_mem_sfence_bits_hv;
    sfence_d1_hg        <= io_ooo_to_mem_sfence_bits_hg;
    sfence_valid        <= sfence_d1_valid;
    sfence_rs1          <= sfence_d1_rs1;
    sfence_rs2          <= sfence_d1_rs2;
    sfence_addr         <= sfence_d1_addr;
    sfence_id           <= sfence_d1_id;
    sfence_flushPipe    <= sfence_d1_flushPipe;
    sfence_hv           <= sfence_d1_hv;
    sfence_hg           <= sfence_d1_hg;
  end

  logic [3:0]   tlbcsr_d1_satp_mode, tlbcsr_d1_vsatp_mode, tlbcsr_d1_hgatp_mode;
  logic [15:0]  tlbcsr_d1_satp_asid, tlbcsr_d1_vsatp_asid, tlbcsr_d1_hgatp_vmid;
  logic [43:0]  tlbcsr_d1_satp_ppn, tlbcsr_d1_vsatp_ppn, tlbcsr_d1_hgatp_ppn;
  logic         tlbcsr_d1_satp_changed, tlbcsr_d1_vsatp_changed, tlbcsr_d1_hgatp_changed;
  logic         tlbcsr_d1_mbmc_BME, tlbcsr_d1_mbmc_CMODE, tlbcsr_d1_mbmc_BCLEAR;
  logic [57:0]  tlbcsr_d1_mbmc_BMA;
  logic         tlbcsr_d1_priv_mxr, tlbcsr_d1_priv_sum, tlbcsr_d1_priv_vmxr, tlbcsr_d1_priv_vsum;
  logic         tlbcsr_d1_priv_virt, tlbcsr_d1_priv_virt_changed, tlbcsr_d1_priv_spvp, tlbcsr_d1_priv_debug;
  logic [1:0]   tlbcsr_d1_priv_imode, tlbcsr_d1_priv_dmode;
  logic         tlbcsr_d1_mPBMTE, tlbcsr_d1_hPBMTE;
  logic [1:0]   tlbcsr_d1_pmm_mseccfg, tlbcsr_d1_pmm_menvcfg, tlbcsr_d1_pmm_henvcfg, tlbcsr_d1_pmm_hstatus;
  logic [1:0]   tlbcsr_d1_pmm_senvcfg;
  always_ff @(posedge clock) begin
    // 第一拍
    tlbcsr_d1_satp_mode         <= io_ooo_to_mem_tlbCsr_satp_mode;
    tlbcsr_d1_satp_asid         <= io_ooo_to_mem_tlbCsr_satp_asid;
    tlbcsr_d1_satp_ppn          <= io_ooo_to_mem_tlbCsr_satp_ppn;
    tlbcsr_d1_satp_changed      <= io_ooo_to_mem_tlbCsr_satp_changed;
    tlbcsr_d1_vsatp_mode        <= io_ooo_to_mem_tlbCsr_vsatp_mode;
    tlbcsr_d1_vsatp_asid        <= io_ooo_to_mem_tlbCsr_vsatp_asid;
    tlbcsr_d1_vsatp_ppn         <= io_ooo_to_mem_tlbCsr_vsatp_ppn;
    tlbcsr_d1_vsatp_changed     <= io_ooo_to_mem_tlbCsr_vsatp_changed;
    tlbcsr_d1_hgatp_mode        <= io_ooo_to_mem_tlbCsr_hgatp_mode;
    tlbcsr_d1_hgatp_vmid        <= io_ooo_to_mem_tlbCsr_hgatp_vmid;
    tlbcsr_d1_hgatp_ppn         <= io_ooo_to_mem_tlbCsr_hgatp_ppn;
    tlbcsr_d1_hgatp_changed     <= io_ooo_to_mem_tlbCsr_hgatp_changed;
    tlbcsr_d1_mbmc_BME          <= io_ooo_to_mem_tlbCsr_mbmc_BME;
    tlbcsr_d1_mbmc_CMODE        <= io_ooo_to_mem_tlbCsr_mbmc_CMODE;
    tlbcsr_d1_mbmc_BCLEAR       <= io_ooo_to_mem_tlbCsr_mbmc_BCLEAR;
    tlbcsr_d1_mbmc_BMA          <= io_ooo_to_mem_tlbCsr_mbmc_BMA;
    tlbcsr_d1_priv_mxr          <= io_ooo_to_mem_tlbCsr_priv_mxr;
    tlbcsr_d1_priv_sum          <= io_ooo_to_mem_tlbCsr_priv_sum;
    tlbcsr_d1_priv_vmxr         <= io_ooo_to_mem_tlbCsr_priv_vmxr;
    tlbcsr_d1_priv_vsum         <= io_ooo_to_mem_tlbCsr_priv_vsum;
    tlbcsr_d1_priv_virt         <= io_ooo_to_mem_tlbCsr_priv_virt;
    tlbcsr_d1_priv_virt_changed <= io_ooo_to_mem_tlbCsr_priv_virt_changed;
    tlbcsr_d1_priv_spvp         <= io_ooo_to_mem_tlbCsr_priv_spvp;
    tlbcsr_d1_priv_imode        <= io_ooo_to_mem_tlbCsr_priv_imode;
    tlbcsr_d1_priv_dmode        <= io_ooo_to_mem_tlbCsr_priv_dmode;
    tlbcsr_d1_priv_debug        <= io_ooo_to_mem_tlbCsr_priv_debug;
    tlbcsr_d1_mPBMTE            <= io_ooo_to_mem_tlbCsr_mPBMTE;
    tlbcsr_d1_hPBMTE            <= io_ooo_to_mem_tlbCsr_hPBMTE;
    tlbcsr_d1_pmm_mseccfg       <= io_ooo_to_mem_tlbCsr_pmm_mseccfg;
    tlbcsr_d1_pmm_menvcfg       <= io_ooo_to_mem_tlbCsr_pmm_menvcfg;
    tlbcsr_d1_pmm_henvcfg       <= io_ooo_to_mem_tlbCsr_pmm_henvcfg;
    tlbcsr_d1_pmm_hstatus       <= io_ooo_to_mem_tlbCsr_pmm_hstatus;
    tlbcsr_d1_pmm_senvcfg       <= io_ooo_to_mem_tlbCsr_pmm_senvcfg;
    // 第二拍（送出）
    tlbcsr_satp_mode            <= tlbcsr_d1_satp_mode;
    tlbcsr_satp_asid            <= tlbcsr_d1_satp_asid;
    tlbcsr_satp_ppn             <= tlbcsr_d1_satp_ppn;
    tlbcsr_satp_changed         <= tlbcsr_d1_satp_changed;
    tlbcsr_vsatp_mode           <= tlbcsr_d1_vsatp_mode;
    tlbcsr_vsatp_asid           <= tlbcsr_d1_vsatp_asid;
    tlbcsr_vsatp_ppn            <= tlbcsr_d1_vsatp_ppn;
    tlbcsr_vsatp_changed        <= tlbcsr_d1_vsatp_changed;
    tlbcsr_hgatp_mode           <= tlbcsr_d1_hgatp_mode;
    tlbcsr_hgatp_vmid           <= tlbcsr_d1_hgatp_vmid;
    tlbcsr_hgatp_ppn            <= tlbcsr_d1_hgatp_ppn;
    tlbcsr_hgatp_changed        <= tlbcsr_d1_hgatp_changed;
    tlbcsr_mbmc_BME             <= tlbcsr_d1_mbmc_BME;
    tlbcsr_mbmc_CMODE           <= tlbcsr_d1_mbmc_CMODE;
    tlbcsr_mbmc_BCLEAR          <= tlbcsr_d1_mbmc_BCLEAR;
    tlbcsr_mbmc_BMA             <= tlbcsr_d1_mbmc_BMA;
    tlbcsr_priv_mxr             <= tlbcsr_d1_priv_mxr;
    tlbcsr_priv_sum             <= tlbcsr_d1_priv_sum;
    tlbcsr_priv_vmxr            <= tlbcsr_d1_priv_vmxr;
    tlbcsr_priv_vsum            <= tlbcsr_d1_priv_vsum;
    tlbcsr_priv_virt            <= tlbcsr_d1_priv_virt;
    tlbcsr_priv_virt_changed    <= tlbcsr_d1_priv_virt_changed;
    tlbcsr_priv_spvp            <= tlbcsr_d1_priv_spvp;
    tlbcsr_priv_imode           <= tlbcsr_d1_priv_imode;
    tlbcsr_priv_dmode           <= tlbcsr_d1_priv_dmode;
    tlbcsr_priv_debug           <= tlbcsr_d1_priv_debug;
    tlbcsr_mPBMTE               <= tlbcsr_d1_mPBMTE;
    tlbcsr_hPBMTE               <= tlbcsr_d1_hPBMTE;
    tlbcsr_pmm_mseccfg          <= tlbcsr_d1_pmm_mseccfg;
    tlbcsr_pmm_menvcfg          <= tlbcsr_d1_pmm_menvcfg;
    tlbcsr_pmm_henvcfg          <= tlbcsr_d1_pmm_henvcfg;
    tlbcsr_pmm_hstatus          <= tlbcsr_d1_pmm_hstatus;
    tlbcsr_pmm_senvcfg          <= tlbcsr_d1_pmm_senvcfg;
  end

  // ===========================================================================
  // §3 DTLB 回填
  //   PTW 的回应（ptwio.resp，来自 PTWNewFilter）打一拍成 ptw_resp_next（RegEnable，只在 valid 时更新），
  //   ptw_resp_v 是它的 valid —— 中间若有 sfence 或地址空间切换（satp/vsatp/hgatp/virt 变了）就作废。
  //   打拍后的回应同时广播给三个 DTLB（各看自己那一组 vector 位），并做两件事：
  //     (a) 8 个 DTLB 缺失请求（load 4 / store 2 / 预取 2）里，若正好能被这条回应命中，就不再发给 PTW
  //         （ptwio.req(i).valid := tlb.valid && !(ptw_resp_v && vector_hit && hit(vpn))）；
  //     (b) load 流水 0..2 的请求若能命中，记为"重放"（tlbreplay），打一拍后作为 tlb_hint.full 告诉 load 流水
  //         "不必等 PTW 回应，直接重放"，与 DTLB 自己报的 tlbreplay 一起或上。
  //   命中判定 = PtwRespS2.hit(vpn, allType=true, ignoreAsid=true)，按两级翻译模式 s2xlate 分三种：
  //     noS2xlate   → 只看第一级（扇区式 TLB 项：tag 比到 level 对应的那几段，非超级页还要看 valididx）
  //     onlyStage2  → 只看第二级（G-stage 项，带 vmid 比较）
  //     onlyStage1 / allStage → 第一级 tag 拼上 addr_low 当 vpn 比，level 取两级里更小的那一级，带 vmid 比较
  // ===========================================================================
  localparam logic [1:0] S2_NONE = 2'd0, S2_ONLY_S1 = 2'd1, S2_ONLY_S2 = 2'd2;

  logic ptwResp_forDtlbLd, ptwResp_forDtlbSt, ptwResp_forDtlbPf;   // 回应是给哪个 DTLB 的（vector 各组的首位）
  logic ptwResp_valid;
  always_ff @(posedge clock) begin
    if (dtlbRepeater_tlb_resp_valid) begin
      ptwResp_s2xlate         <= dtlbRepeater_tlb_resp_bits_data_s2xlate;
      ptwResp_s1_entry_tag    <= dtlbRepeater_tlb_resp_bits_data_s1_entry_tag;
      ptwResp_s1_entry_asid   <= dtlbRepeater_tlb_resp_bits_data_s1_entry_asid;
      ptwResp_s1_entry_vmid   <= dtlbRepeater_tlb_resp_bits_data_s1_entry_vmid;
      ptwResp_s1_entry_n      <= dtlbRepeater_tlb_resp_bits_data_s1_entry_n;
      ptwResp_s1_entry_pbmt   <= dtlbRepeater_tlb_resp_bits_data_s1_entry_pbmt;
      ptwResp_s1_entry_perm_d <= dtlbRepeater_tlb_resp_bits_data_s1_entry_perm_d;
      ptwResp_s1_entry_perm_a <= dtlbRepeater_tlb_resp_bits_data_s1_entry_perm_a;
      ptwResp_s1_entry_perm_g <= dtlbRepeater_tlb_resp_bits_data_s1_entry_perm_g;
      ptwResp_s1_entry_perm_u <= dtlbRepeater_tlb_resp_bits_data_s1_entry_perm_u;
      ptwResp_s1_entry_perm_x <= dtlbRepeater_tlb_resp_bits_data_s1_entry_perm_x;
      ptwResp_s1_entry_perm_w <= dtlbRepeater_tlb_resp_bits_data_s1_entry_perm_w;
      ptwResp_s1_entry_perm_r <= dtlbRepeater_tlb_resp_bits_data_s1_entry_perm_r;
      ptwResp_s1_entry_level  <= dtlbRepeater_tlb_resp_bits_data_s1_entry_level;
      ptwResp_s1_entry_v      <= dtlbRepeater_tlb_resp_bits_data_s1_entry_v;
      ptwResp_s1_entry_ppn    <= dtlbRepeater_tlb_resp_bits_data_s1_entry_ppn;
      ptwResp_s1_addr_low     <= dtlbRepeater_tlb_resp_bits_data_s1_addr_low;
      ptwResp_s1_ppn_low[0]   <= dtlbRepeater_tlb_resp_bits_data_s1_ppn_low_0;
      ptwResp_s1_ppn_low[1]   <= dtlbRepeater_tlb_resp_bits_data_s1_ppn_low_1;
      ptwResp_s1_ppn_low[2]   <= dtlbRepeater_tlb_resp_bits_data_s1_ppn_low_2;
      ptwResp_s1_ppn_low[3]   <= dtlbRepeater_tlb_resp_bits_data_s1_ppn_low_3;
      ptwResp_s1_ppn_low[4]   <= dtlbRepeater_tlb_resp_bits_data_s1_ppn_low_4;
      ptwResp_s1_ppn_low[5]   <= dtlbRepeater_tlb_resp_bits_data_s1_ppn_low_5;
      ptwResp_s1_ppn_low[6]   <= dtlbRepeater_tlb_resp_bits_data_s1_ppn_low_6;
      ptwResp_s1_ppn_low[7]   <= dtlbRepeater_tlb_resp_bits_data_s1_ppn_low_7;
      ptwResp_s1_valididx[0]  <= dtlbRepeater_tlb_resp_bits_data_s1_valididx_0;
      ptwResp_s1_valididx[1]  <= dtlbRepeater_tlb_resp_bits_data_s1_valididx_1;
      ptwResp_s1_valididx[2]  <= dtlbRepeater_tlb_resp_bits_data_s1_valididx_2;
      ptwResp_s1_valididx[3]  <= dtlbRepeater_tlb_resp_bits_data_s1_valididx_3;
      ptwResp_s1_valididx[4]  <= dtlbRepeater_tlb_resp_bits_data_s1_valididx_4;
      ptwResp_s1_valididx[5]  <= dtlbRepeater_tlb_resp_bits_data_s1_valididx_5;
      ptwResp_s1_valididx[6]  <= dtlbRepeater_tlb_resp_bits_data_s1_valididx_6;
      ptwResp_s1_valididx[7]  <= dtlbRepeater_tlb_resp_bits_data_s1_valididx_7;
      ptwResp_s1_pteidx[0]    <= dtlbRepeater_tlb_resp_bits_data_s1_pteidx_0;
      ptwResp_s1_pteidx[1]    <= dtlbRepeater_tlb_resp_bits_data_s1_pteidx_1;
      ptwResp_s1_pteidx[2]    <= dtlbRepeater_tlb_resp_bits_data_s1_pteidx_2;
      ptwResp_s1_pteidx[3]    <= dtlbRepeater_tlb_resp_bits_data_s1_pteidx_3;
      ptwResp_s1_pteidx[4]    <= dtlbRepeater_tlb_resp_bits_data_s1_pteidx_4;
      ptwResp_s1_pteidx[5]    <= dtlbRepeater_tlb_resp_bits_data_s1_pteidx_5;
      ptwResp_s1_pteidx[6]    <= dtlbRepeater_tlb_resp_bits_data_s1_pteidx_6;
      ptwResp_s1_pteidx[7]    <= dtlbRepeater_tlb_resp_bits_data_s1_pteidx_7;
      ptwResp_s1_pf           <= dtlbRepeater_tlb_resp_bits_data_s1_pf;
      ptwResp_s1_af           <= dtlbRepeater_tlb_resp_bits_data_s1_af;
      ptwResp_s2_entry_tag    <= dtlbRepeater_tlb_resp_bits_data_s2_entry_tag;
      ptwResp_s2_entry_vmid   <= dtlbRepeater_tlb_resp_bits_data_s2_entry_vmid;
      ptwResp_s2_entry_n      <= dtlbRepeater_tlb_resp_bits_data_s2_entry_n;
      ptwResp_s2_entry_pbmt   <= dtlbRepeater_tlb_resp_bits_data_s2_entry_pbmt;
      ptwResp_s2_entry_ppn    <= dtlbRepeater_tlb_resp_bits_data_s2_entry_ppn;
      ptwResp_s2_entry_perm_d <= dtlbRepeater_tlb_resp_bits_data_s2_entry_perm_d;
      ptwResp_s2_entry_perm_a <= dtlbRepeater_tlb_resp_bits_data_s2_entry_perm_a;
      ptwResp_s2_entry_perm_g <= dtlbRepeater_tlb_resp_bits_data_s2_entry_perm_g;
      ptwResp_s2_entry_perm_u <= dtlbRepeater_tlb_resp_bits_data_s2_entry_perm_u;
      ptwResp_s2_entry_perm_x <= dtlbRepeater_tlb_resp_bits_data_s2_entry_perm_x;
      ptwResp_s2_entry_perm_w <= dtlbRepeater_tlb_resp_bits_data_s2_entry_perm_w;
      ptwResp_s2_entry_perm_r <= dtlbRepeater_tlb_resp_bits_data_s2_entry_perm_r;
      ptwResp_s2_entry_level  <= dtlbRepeater_tlb_resp_bits_data_s2_entry_level;
      ptwResp_s2_gpf          <= dtlbRepeater_tlb_resp_bits_data_s2_gpf;
      ptwResp_s2_gaf          <= dtlbRepeater_tlb_resp_bits_data_s2_gaf;
      // vector：8 个 DTLB 请求口里谁在等这条回应；本配置下只有每组的首位（0 / 4 / 6）连着
      ptwResp_forDtlbLd       <= dtlbRepeater_tlb_resp_bits_vector_0;
      ptwResp_forDtlbSt       <= dtlbRepeater_tlb_resp_bits_vector_4;
      ptwResp_forDtlbPf       <= dtlbRepeater_tlb_resp_bits_vector_6;
      ptwResp_getGpaLd        <= dtlbRepeater_tlb_resp_bits_getGpa_0;
      ptwResp_getGpaSt        <= dtlbRepeater_tlb_resp_bits_getGpa_4;
      ptwResp_getGpaPf        <= dtlbRepeater_tlb_resp_bits_getGpa_6;
    end
  end
  always_ff @(posedge clock or posedge reset) begin
    if (reset) ptwResp_valid <= 1'b0;
    else       ptwResp_valid <= dtlbRepeater_tlb_resp_valid
                                & ~(sfence_valid | tlbcsr_satp_changed | tlbcsr_vsatp_changed
                                    | tlbcsr_hgatp_changed | tlbcsr_priv_virt_changed);
  end
  assign dtlbLd_ptw_resp_valid = ptwResp_valid & ptwResp_forDtlbLd;
  assign dtlbSt_ptw_resp_valid = ptwResp_valid & ptwResp_forDtlbSt;
  assign dtlbPf_ptw_resp_valid = ptwResp_valid & ptwResp_forDtlbPf;

  // ---- 命中判定（对 8 个缺失请求各算一遍）----
  //   vpn 38 位 = 4 段 × 9 位（最高段 11 位）；扇区式第一级 TLB 项的 tag 少低 3 位（sectortlbwidth），
  //   那 3 位由 addr_low（onlyStage1/allStage）或 valididx（noS2xlate 非超级页）补上；NAPOT（n=1）的 64KB 页只比到 vpn[8:4]。
  logic        req_valid [8];
  logic [37:0] req_vpn   [8];
  logic        req_group_hit [8];            // 回应是否就是给这个请求所在的那个 DTLB 的
  assign req_valid[0] = dtlbLd_ptw_req_0_valid;  assign req_vpn[0] = dtlbLd_ptw_req_0_bits_vpn;
  assign req_valid[1] = dtlbLd_ptw_req_1_valid;  assign req_vpn[1] = dtlbLd_ptw_req_1_bits_vpn;
  assign req_valid[2] = dtlbLd_ptw_req_2_valid;  assign req_vpn[2] = dtlbLd_ptw_req_2_bits_vpn;
  assign req_valid[3] = dtlbLd_ptw_req_3_valid;  assign req_vpn[3] = dtlbLd_ptw_req_3_bits_vpn;
  assign req_valid[4] = dtlbSt_ptw_req_0_valid;  assign req_vpn[4] = dtlbSt_ptw_req_0_bits_vpn;
  assign req_valid[5] = dtlbSt_ptw_req_1_valid;  assign req_vpn[5] = dtlbSt_ptw_req_1_bits_vpn;
  assign req_valid[6] = dtlbPf_ptw_req_0_valid;  assign req_vpn[6] = dtlbPf_ptw_req_0_bits_vpn;
  assign req_valid[7] = dtlbPf_ptw_req_1_valid;  assign req_vpn[7] = dtlbPf_ptw_req_1_bits_vpn;
  assign req_group_hit[0] = ptwResp_forDtlbLd;
  assign req_group_hit[1] = ptwResp_forDtlbLd;
  assign req_group_hit[2] = ptwResp_forDtlbLd;
  assign req_group_hit[3] = ptwResp_forDtlbLd;
  assign req_group_hit[4] = ptwResp_forDtlbSt;
  assign req_group_hit[5] = ptwResp_forDtlbSt;
  assign req_group_hit[6] = ptwResp_forDtlbPf;
  assign req_group_hit[7] = ptwResp_forDtlbPf;

  // 与请求无关的那部分：两级合并后的页大小（level 取小的那一级）与 NAPOT 标志、vmid 是否匹配
  logic [1:0] merged_level;
  logic       merged_napot;
  logic       s1_vmid_hit, s2_vmid_hit;
  assign merged_level = (ptwResp_s2xlate == S2_ONLY_S1 || ptwResp_s1_entry_level < ptwResp_s2_entry_level)
                        ? ptwResp_s1_entry_level : ptwResp_s2_entry_level;
  //   allStage 时 64KB 页成立的三种情况：s1 是 NAPOT 而 s2 是超级页；s2 是 NAPOT 而 s1 是超级页；两级都是 NAPOT
  assign merged_napot = (ptwResp_s2xlate == S2_ONLY_S1)
                        ? ptwResp_s1_entry_n
                        : (ptwResp_s1_entry_n & (ptwResp_s2_entry_level != 2'd0))
                          | (ptwResp_s2_entry_n & (ptwResp_s1_entry_level != 2'd0))
                          | (ptwResp_s1_entry_n & ptwResp_s2_entry_n);
  assign s1_vmid_hit = {2'b00, ptwResp_s1_entry_vmid} == tlbcsr_hgatp_vmid;
  assign s2_vmid_hit = {2'b00, ptwResp_s2_entry_vmid} == tlbcsr_hgatp_vmid;

  logic req_hit [8];
  for (genvar r = 0; r < 8; r++) begin : g_resp_hit
    // noS2xlate：第一级扇区项。tag[34:0] 对应 vpn[37:3]
    logic s1_tm0, s1_tm1, s1_tm2, s1_tm3, s1_level_match, s1_low_hit, noS2_hit;
    assign s1_tm0 = ptwResp_s1_entry_n ? (ptwResp_s1_entry_tag[5:1] == req_vpn[r][8:4])
                                       : (ptwResp_s1_entry_tag[5:0] == req_vpn[r][8:3]);
    assign s1_tm1 = ptwResp_s1_entry_tag[14:6]  == req_vpn[r][17:9];
    assign s1_tm2 = ptwResp_s1_entry_tag[23:15] == req_vpn[r][26:18];
    assign s1_tm3 = ptwResp_s1_entry_tag[34:24] == req_vpn[r][37:27];
    always_comb begin
      unique case (ptwResp_s1_entry_level)
        2'd3:    s1_level_match = s1_tm3;
        2'd2:    s1_level_match = s1_tm3 & s1_tm2;
        2'd1:    s1_level_match = s1_tm3 & s1_tm2 & s1_tm1;
        default: s1_level_match = s1_tm3 & s1_tm2 & s1_tm1 & s1_tm0;
      endcase
    end
    // 超级页（level≠0）或 NAPOT 页不分扇区；否则看扇区内这一项是否有效
    assign s1_low_hit = (ptwResp_s1_entry_level != 2'd0) | ptwResp_s1_entry_n
                        | ptwResp_s1_valididx[req_vpn[r][2:0]];
    assign noS2_hit = s1_level_match & s1_low_hit;

    // onlyStage2：第二级（G-stage）项，tag 是完整的 38 位 gvpn
    logic s2_tm0, s2_tm1, s2_tm2, s2_tm3, s2_level_match, onlyS2_hit;
    assign s2_tm0 = ptwResp_s2_entry_n ? (ptwResp_s2_entry_tag[8:4] == req_vpn[r][8:4])
                                       : (ptwResp_s2_entry_tag[8:0] == req_vpn[r][8:0]);
    assign s2_tm1 = ptwResp_s2_entry_tag[17:9]  == req_vpn[r][17:9];
    assign s2_tm2 = ptwResp_s2_entry_tag[26:18] == req_vpn[r][26:18];
    assign s2_tm3 = ptwResp_s2_entry_tag[37:27] == req_vpn[r][37:27];
    always_comb begin
      unique case (ptwResp_s2_entry_level)
        2'd3:    s2_level_match = s2_tm3;
        2'd2:    s2_level_match = s2_tm3 & s2_tm2;
        2'd1:    s2_level_match = s2_tm3 & s2_tm2 & s2_tm1;
        default: s2_level_match = s2_tm3 & s2_tm2 & s2_tm1 & s2_tm0;
      endcase
    end
    assign onlyS2_hit = s2_vmid_hit & s2_level_match;

    // onlyStage1 / allStage：第一级 tag 拼上 addr_low 成完整 vpn；页大小取两级里更小的
    logic [37:0] s1_vpn;
    logic        a_tm0, a_tm1, a_tm2, a_tm3, a_level_match, all_onlyS1_hit;
    assign s1_vpn = {ptwResp_s1_entry_tag, ptwResp_s1_addr_low};
    assign a_tm0 = merged_napot ? (req_vpn[r][8:4] == s1_vpn[8:4]) : (req_vpn[r][8:0] == s1_vpn[8:0]);
    assign a_tm1 = req_vpn[r][17:9]  == s1_vpn[17:9];
    assign a_tm2 = req_vpn[r][26:18] == s1_vpn[26:18];
    assign a_tm3 = req_vpn[r][37:27] == s1_vpn[37:27];
    always_comb begin
      unique case (merged_level)
        2'd3:    a_level_match = a_tm3;
        2'd2:    a_level_match = a_tm3 & a_tm2;
        2'd1:    a_level_match = a_tm3 & a_tm2 & a_tm1;
        default: a_level_match = a_tm3 & a_tm2 & a_tm1 & a_tm0;
      endcase
    end
    assign all_onlyS1_hit = a_level_match & s1_vmid_hit;

    assign req_hit[r] = (ptwResp_s2xlate == S2_NONE)    ? noS2_hit
                      : (ptwResp_s2xlate == S2_ONLY_S2) ? onlyS2_hit
                      :                                   all_onlyS1_hit;
  end

  // (a) 能被这条回应直接满足的缺失请求不再发往 PTW
  logic resp_covers [8];
  for (genvar r = 0; r < 8; r++) begin : g_resp_covers
    assign resp_covers[r] = ptwResp_valid & req_group_hit[r] & req_hit[r];
  end
  assign dtlbRepeater_tlb_req_0_valid = req_valid[0] & ~resp_covers[0];
  assign dtlbRepeater_tlb_req_1_valid = req_valid[1] & ~resp_covers[1];
  assign dtlbRepeater_tlb_req_2_valid = req_valid[2] & ~resp_covers[2];
  assign dtlbRepeater_tlb_req_3_valid = req_valid[3] & ~resp_covers[3];
  assign dtlbRepeater_tlb_req_4_valid = req_valid[4] & ~resp_covers[4];
  assign dtlbRepeater_tlb_req_5_valid = req_valid[5] & ~resp_covers[5];
  assign dtlbRepeater_tlb_req_6_valid = req_valid[6] & ~resp_covers[6];
  assign dtlbRepeater_tlb_req_7_valid = req_valid[7] & ~resp_covers[7];

  // (b) load 流水 0..2 的重放提示：本层算出的 tlbreplay 与 DTLB 自报的 tlbreplay 各打一拍（异步复位 0）
  logic tlbReplay_q [3];
  logic dtlbLdReplay_q [4];
  always_ff @(posedge clock or posedge reset) begin
    if (reset) begin
      for (int k = 0; k < 3; k++) tlbReplay_q[k] <= 1'b0;
      for (int k = 0; k < 4; k++) dtlbLdReplay_q[k] <= 1'b0;
    end else begin
      for (int k = 0; k < 3; k++) tlbReplay_q[k] <= req_valid[k] & resp_covers[k];
      dtlbLdReplay_q[0] <= dtlbLd_tlbreplay_0;
      dtlbLdReplay_q[1] <= dtlbLd_tlbreplay_1;
      dtlbLdReplay_q[2] <= dtlbLd_tlbreplay_2;
      dtlbLdReplay_q[3] <= dtlbLd_tlbreplay_3;
    end
  end
  assign ldu0_tlb_hint_full = dtlbRepeater_hint_req_0_full | tlbReplay_q[0] | dtlbLdReplay_q[0];
  assign ldu1_tlb_hint_full = dtlbRepeater_hint_req_1_full | tlbReplay_q[1] | dtlbLdReplay_q[1];
  assign ldu2_tlb_hint_full = dtlbRepeater_hint_req_2_full | tlbReplay_q[2] | dtlbLdReplay_q[2];

  // ===========================================================================
  // §4 访存触发器（debug trigger）：4 组 tdata 由 CSR 的 tUpdate 按地址写入，tEnable 逐拍跟随（均异步复位 0）。
  //   tdata.timing：CSR 写来的值在本配置下恒 0（golden 里 csrCtrl 延迟线上没有这一位），写入即清 0。
  // ===========================================================================
  always_ff @(posedge clock or posedge reset) begin
    if (reset) begin
      for (int k = 0; k < 4; k++) begin
        trig_matchType[k] <= 2'b0;
        trig_select[k]    <= 1'b0;
        trig_timing[k]    <= 1'b0;
        trig_action[k]    <= 4'b0;
        trig_chain[k]     <= 1'b0;
        trig_store[k]     <= 1'b0;
        trig_load[k]      <= 1'b0;
        trig_tdata2[k]    <= 64'b0;
        trig_enable[k]    <= 1'b0;
      end
    end else begin
      for (int k = 0; k < 4; k++) begin
        if (csrCtrlDly_out_mem_trigger_tUpdate_valid && csrCtrlDly_out_mem_trigger_tUpdate_bits_addr == 2'(k)) begin
          trig_matchType[k] <= csrCtrlDly_out_mem_trigger_tUpdate_bits_tdata_matchType;
          trig_select[k]    <= csrCtrlDly_out_mem_trigger_tUpdate_bits_tdata_select;
          trig_timing[k]    <= 1'b0;
          trig_action[k]    <= csrCtrlDly_out_mem_trigger_tUpdate_bits_tdata_action;
          trig_chain[k]     <= csrCtrlDly_out_mem_trigger_tUpdate_bits_tdata_chain;
          trig_store[k]     <= csrCtrlDly_out_mem_trigger_tUpdate_bits_tdata_store;
          trig_load[k]      <= csrCtrlDly_out_mem_trigger_tUpdate_bits_tdata_load;
          trig_tdata2[k]    <= csrCtrlDly_out_mem_trigger_tUpdate_bits_tdata_tdata2;
        end
      end
      trig_enable[0] <= csrCtrlDly_out_mem_trigger_tEnableVec_0;
      trig_enable[1] <= csrCtrlDly_out_mem_trigger_tEnableVec_1;
      trig_enable[2] <= csrCtrlDly_out_mem_trigger_tEnableVec_2;
      trig_enable[3] <= csrCtrlDly_out_mem_trigger_tEnableVec_3;
    end
  end

  // ===========================================================================
  // §5 load 口 0 的三方共享
  //   vector segment 指令原子地执行：seg_active 期间它独占 DCache load 口 0（三条 load 流水的 DCache 请求都
  //   被挡住），也借用 DTLB 口 0；原子指令执行期间（amo_state≠空闲）借用 DTLB 口 0。
  //   seg_active：segment 指令发射后一拍置位，segment 写回后一拍清零（GatedValidRegNext 的 fire 打一拍）；
  //   VSegmentUnit 在 golden 里没有 in.ready 端口（恒接收），所以"发射"就是 segment_issue_valid。
  //   刚接管的那一拍（seg_active && !seg_active_q）把口 0 上 S1 级残留的请求杀掉（只可能是硬件预取）。
  // ===========================================================================
  logic seg_start_q, seg_done_q, seg_active, seg_active_q;
  always_ff @(posedge clock or posedge reset) begin
    if (reset) begin
      seg_start_q  <= 1'b0;
      seg_done_q   <= 1'b0;
      seg_active   <= 1'b0;
      seg_active_q <= 1'b0;
    end else begin
      seg_start_q  <= segment_issue_valid;
      seg_done_q   <= vSeg_uopwriteback_valid;
      if (seg_start_q)      seg_active <= 1'b1;
      else if (seg_done_q)  seg_active <= 1'b0;
      seg_active_q <= seg_active;
    end
  end

  // DCache load 口 0：请求 = load 流水 0 与 segment 独热合一（Mux1H）；S1/S2 侧的控制在 seg_active 时取 segment 的。
  //   segment 侧在本配置下没有的字段（cmd / instrtype / isFirstIssue / lqIdx / pf_source / kill 类）按 0 处理。
  assign dcache_lsu_load_0_req_valid            = ldu0_dcache_req_valid | vSeg_rdcache_req_valid;
  assign dcache_lsu_load_0_req_bits_cmd         = ldu0_dcache_req_valid ? ldu0_dcache_req_bits_cmd : 5'b0;
  assign dcache_lsu_load_0_req_bits_vaddr       = (vSeg_rdcache_req_valid ? vSeg_rdcache_req_bits_vaddr : 50'b0)
                                                | (ldu0_dcache_req_valid  ? ldu0_dcache_req_bits_vaddr  : 50'b0);
  assign dcache_lsu_load_0_req_bits_vaddr_dup   = (vSeg_rdcache_req_valid ? vSeg_rdcache_req_bits_vaddr_dup : 50'b0)
                                                | (ldu0_dcache_req_valid  ? ldu0_dcache_req_bits_vaddr_dup  : 50'b0);
  assign dcache_lsu_load_0_req_bits_instrtype   = ldu0_dcache_req_valid ? ldu0_dcache_req_bits_instrtype : 4'b0;
  assign dcache_lsu_load_0_req_bits_isFirstIssue = ldu0_dcache_req_valid & ldu0_dcache_req_bits_isFirstIssue;
  assign dcache_lsu_load_0_req_bits_lqIdx_flag  = ldu0_dcache_req_valid & ldu0_dcache_req_bits_lqIdx_flag;
  assign dcache_lsu_load_0_req_bits_lqIdx_value = ldu0_dcache_req_valid ? ldu0_dcache_req_bits_lqIdx_value : 7'b0;
  assign dcache_lsu_load_0_s1_kill_data_read    = seg_active ? 1'b0 : ldu0_dcache_s1_kill_data_read;
  assign dcache_lsu_load_0_s1_kill              = seg_active ? (seg_active & ~seg_active_q) : ldu0_dcache_s1_kill;
  assign dcache_lsu_load_0_s2_kill              = seg_active ? 1'b0 : ldu0_dcache_s2_kill;
  assign dcache_lsu_load_0_is128Req             = seg_active ? vSeg_rdcache_is128Req : ldu0_dcache_is128Req;
  assign dcache_lsu_load_0_pf_source            = seg_active ? 3'b0 : ldu0_dcache_pf_source;
  assign dcache_lsu_load_0_s1_paddr_dup_lsu     = seg_active ? vSeg_rdcache_s1_paddr_dup_lsu    : ldu0_dcache_s1_paddr_dup_lsu;
  assign dcache_lsu_load_0_s1_paddr_dup_dcache  = seg_active ? vSeg_rdcache_s1_paddr_dup_dcache : ldu0_dcache_s1_paddr_dup_dcache;
  // segment 独占期间三条 load 流水都拿不到 DCache
  assign ldu0_dcache_req_ready = ~seg_active & dcache_lsu_load_0_req_ready;
  assign ldu1_dcache_req_ready = ~seg_active & dcache_lsu_load_1_req_ready;
  assign ldu2_dcache_req_ready = ~seg_active & dcache_lsu_load_2_req_ready;

  // DTLB 口 0：优先级 原子指令（amo_state≠空闲时它直接接管）> segment（请求晚一拍送达）> load 流水 0。
  //   segment 的 DTLB 请求要延迟一拍（RegNext(valid) + RegEnable(bits)），golden 里 valid 打拍有两份（valid / 选择各一份）。
  logic        segTlb_valid_q, segTlb_sel_q;
  logic [49:0] segTlb_vaddr_q;
  logic [63:0] segTlb_fullva_q;
  logic [2:0]  segTlb_cmd_q;
  logic        segTlb_robIdx_flag_q;
  logic [7:0]  segTlb_robIdx_value_q;
  always_ff @(posedge clock) begin
    segTlb_valid_q <= vSeg_dtlb_req_valid;
    segTlb_sel_q   <= vSeg_dtlb_req_valid;
    if (vSeg_dtlb_req_valid) begin
      segTlb_vaddr_q        <= vSeg_dtlb_req_bits_vaddr;
      segTlb_fullva_q       <= vSeg_dtlb_req_bits_fullva;
      segTlb_cmd_q          <= vSeg_dtlb_req_bits_cmd;
      segTlb_robIdx_flag_q  <= vSeg_dtlb_req_bits_debug_robIdx_flag;
      segTlb_robIdx_value_q <= vSeg_dtlb_req_bits_debug_robIdx_value;
    end
  end
  logic [1:0] amo_state;
  logic       amo_active;           // 原子指令执行中（amo_state≠空闲）
  logic       tlb0_borrowed;        // DTLB 口 0 被原子指令或 segment 占用
  assign amo_active    = amo_state != 2'd0;
  assign tlb0_borrowed = amo_active | segTlb_sel_q;
  assign dtlbLd_requestor_0_req_valid = amo_active ? amo_dtlb_req_valid : (ldu0_tlb_req_valid | segTlb_valid_q);
  assign dtlbLd_requestor_0_req_bits_vaddr  = amo_active ? amo_dtlb_req_bits_vaddr
                                            : segTlb_sel_q ? segTlb_vaddr_q : ldu0_tlb_req_bits_vaddr;
  assign dtlbLd_requestor_0_req_bits_fullva = amo_active ? amo_dtlb_req_bits_fullva
                                            : segTlb_sel_q ? segTlb_fullva_q : ldu0_tlb_req_bits_fullva;
  assign dtlbLd_requestor_0_req_bits_cmd    = amo_active ? amo_dtlb_req_bits_cmd
                                            : segTlb_sel_q ? segTlb_cmd_q : ldu0_tlb_req_bits_cmd;
  assign dtlbLd_requestor_0_req_bits_debug_robIdx_flag  = amo_active ? amo_dtlb_req_bits_debug_robIdx_flag
                                            : segTlb_sel_q ? segTlb_robIdx_flag_q : ldu0_tlb_req_bits_debug_robIdx_flag;
  assign dtlbLd_requestor_0_req_bits_debug_robIdx_value = amo_active ? amo_dtlb_req_bits_debug_robIdx_value
                                            : segTlb_sel_q ? segTlb_robIdx_value_q : ldu0_tlb_req_bits_debug_robIdx_value;
  // 原子单元与 segment 的请求里这些字段是常量：checkfullva 恒 1，其余恒 0
  assign dtlbLd_requestor_0_req_bits_checkfullva   = tlb0_borrowed | ldu0_tlb_req_bits_checkfullva;
  assign dtlbLd_requestor_0_req_bits_hyperinst     = ~tlb0_borrowed & ldu0_tlb_req_bits_hyperinst;
  assign dtlbLd_requestor_0_req_bits_hlvx          = ~tlb0_borrowed & ldu0_tlb_req_bits_hlvx;
  assign dtlbLd_requestor_0_req_bits_kill          = ~tlb0_borrowed & ldu0_tlb_req_bits_kill;
  assign dtlbLd_requestor_0_req_bits_isPrefetch    = ~tlb0_borrowed & ldu0_tlb_req_bits_isPrefetch;
  assign dtlbLd_requestor_0_req_bits_no_translate  = ~tlb0_borrowed & ldu0_tlb_req_bits_no_translate;
  assign dtlbLd_requestor_0_req_bits_pmp_addr      = tlb0_borrowed ? 48'b0 : ldu0_tlb_req_bits_pmp_addr;
  assign dtlbLd_requestor_0_req_bits_frm_mabuf     = ~tlb0_borrowed & ldu0_tlb_req_bits_frm_mabuf;
  assign dtlbLd_requestor_0_req_bits_debug_isFirstIssue = ~tlb0_borrowed & ldu0_tlb_req_bits_debug_isFirstIssue;
  assign dtlbLd_requestor_0_req_kill = ~amo_active & ldu0_tlb_req_kill;
  assign amo_dtlb_resp_valid = amo_active & dtlbLd_requestor_0_resp_valid;

  // ===========================================================================
  // §6 原子指令
  //   store 地址发射口 i 上来的若是 AMO（fuType 的 mou 位，第 17 位），就不进 store 流水而交给原子单元；
  //   amo_state：0 空闲，1 / 2 = 原子指令占用 store 口 0 / 1（口 1 优先），原子单元写回那拍回到空闲（异步复位 0）。
  //   原子指令执行期间：load 写回口 0 让给原子单元（load 流水 0 的 ldout 不许出），硬件预取请求不进 load 流水，
  //   store 地址发射队列的慢反馈由原子单元回。
  // ===========================================================================
  logic sta0_is_amo, sta1_is_amo;
  assign sta0_is_amo = io_ooo_to_mem_issueSta_0_valid & io_ooo_to_mem_issueSta_0_bits_uop_fuType[17];
  assign sta1_is_amo = io_ooo_to_mem_issueSta_1_valid & io_ooo_to_mem_issueSta_1_bits_uop_fuType[17];
  assign sta0_issue_valid = io_ooo_to_mem_issueSta_0_valid & ~sta0_is_amo;
  assign sta1_issue_valid = io_ooo_to_mem_issueSta_1_valid & ~sta1_is_amo;
  assign io_ooo_to_mem_issueSta_0_ready = sta0_is_amo ? amo_in_ready : stu0_stin_ready;
  assign io_ooo_to_mem_issueSta_1_ready = sta1_is_amo ? amo_in_ready : stu1_stin_ready;
  assign amo_in_valid = sta0_is_amo | sta1_is_amo;
  assign amoIn = ({AMOIN_W{sta0_is_amo}} & amoIn_sta0) | ({AMOIN_W{sta1_is_amo}} & amoIn_sta1);   // Mux1H
  always_ff @(posedge clock or posedge reset) begin
    if (reset)              amo_state <= 2'd0;
    else if (amo_out_valid) amo_state <= 2'd0;
    else if (sta1_is_amo)   amo_state <= 2'd2;
    else if (sta0_is_amo)   amo_state <= 2'd1;
  end
  assign staFb0 = (amo_state == 2'd1) ? staFb0_amo : staFb0_stu;
  assign staFb1 = (amo_state == 2'd2) ? staFb1_amo : staFb1_stu;

  // ===========================================================================
  // §7 store 数据
  //   std 单元的结果正常写进 StoreQueue；若是 AMO 的数据则交给原子单元而不进 StoreQueue。
  //   向量 store 数据（vsSplit 的 vstd）优先占用 StoreQueue 的数据写口，此时 std 被反压（ready=0）。
  //   向量数据的 fuType 是常量（FuType.vstu，第 32 位）。
  // ===========================================================================
  logic std0_is_amo, std1_is_amo;
  assign std0_is_amo = std0_out_valid & std0_out_bits_uop_fuType[17];
  assign std1_is_amo = std1_out_valid & std1_out_bits_uop_fuType[17];
  assign amo_storeDataIn_0_valid = std0_is_amo;
  assign amo_storeDataIn_1_valid = std1_is_amo;
  assign std0_out_ready = ~vsSplit0_vstd_valid;
  assign std1_out_ready = ~vsSplit1_vstd_valid;
  localparam logic [34:0] FUTYPE_VSTU = 35'h1_0000_0000;
  assign lsq_std_storeDataIn_0_valid           = vsSplit0_vstd_valid | (std0_out_valid & ~std0_is_amo);
  assign lsq_std_storeDataIn_0_bits_uop_fuType = vsSplit0_vstd_valid ? FUTYPE_VSTU : std0_out_bits_uop_fuType;
  assign lsq_std_storeDataIn_0_bits_uop_fuOpType = vsSplit0_vstd_valid ? vsSplit0_vstd_bits_uop_fuOpType
                                                                       : std0_out_bits_uop_fuOpType;
  assign lsq_std_storeDataIn_0_bits_uop_sqIdx_flag  = vsSplit0_vstd_valid ? vsSplit0_vstd_bits_uop_sqIdx_flag
                                                                          : std0_out_bits_uop_sqIdx_flag;
  assign lsq_std_storeDataIn_0_bits_uop_sqIdx_value = vsSplit0_vstd_valid ? vsSplit0_vstd_bits_uop_sqIdx_value
                                                                          : std0_out_bits_uop_sqIdx_value;
  assign lsq_std_storeDataIn_0_bits_data = vsSplit0_vstd_valid ? vsSplit0_vstd_bits_data : {64'b0, std0_out_bits_data};
  assign lsq_std_storeDataIn_1_valid           = vsSplit1_vstd_valid | (std1_out_valid & ~std1_is_amo);
  assign lsq_std_storeDataIn_1_bits_uop_fuType = vsSplit1_vstd_valid ? FUTYPE_VSTU : std1_out_bits_uop_fuType;
  assign lsq_std_storeDataIn_1_bits_uop_fuOpType = vsSplit1_vstd_valid ? vsSplit1_vstd_bits_uop_fuOpType
                                                                       : std1_out_bits_uop_fuOpType;
  assign lsq_std_storeDataIn_1_bits_uop_sqIdx_flag  = vsSplit1_vstd_valid ? vsSplit1_vstd_bits_uop_sqIdx_flag
                                                                          : std1_out_bits_uop_sqIdx_flag;
  assign lsq_std_storeDataIn_1_bits_uop_sqIdx_value = vsSplit1_vstd_valid ? vsSplit1_vstd_bits_uop_sqIdx_value
                                                                          : std1_out_bits_uop_sqIdx_value;
  assign lsq_std_storeDataIn_1_bits_data = vsSplit1_vstd_valid ? vsSplit1_vstd_bits_data : {64'b0, std1_out_bits_data};
  // store 数据的写回（给后端标记完成）：std 真的被接收（fire）且不是 AMO
  assign io_mem_to_ooo_writebackStd_0_valid = std0_out_ready & std0_out_valid & ~std0_out_bits_uop_fuType[17];
  assign io_mem_to_ooo_writebackStd_1_valid = std1_out_ready & std1_out_valid & ~std1_out_bits_uop_fuType[17];

  // ===========================================================================
  // §8 写回仲裁
  // ===========================================================================
  // load 写回口 0：原子单元的结果覆盖 load 流水 0（AtomicWBPort = 0）
  assign io_mem_to_ooo_writebackLda_0_valid = amo_out_valid | ldu0_ldout_valid;
  assign wbLda0 = amo_out_valid ? wbLda0_amo : wbLda0_ldu;
  assign ldu0_ldout_ready = ~amo_active & io_mem_to_ooo_writebackLda_0_ready;
  // load 写回口 1：load 流水 1 优先，空出来时给非对齐 load 缓冲（MisalignWBPort = 1）
  assign io_mem_to_ooo_writebackLda_1_valid = lmb_writeBack_valid | ldu1_ldout_valid;
  assign wbLda1 = ldu1_ldout_valid ? wbLda1_ldu : wbLda1_lmb;
  assign lmb_writeBack_ready = io_mem_to_ooo_writebackLda_1_ready & ~ldu1_ldout_valid;

  // store 写回口 0：非对齐 store 缓冲（只在口 0 / 两条向量结果都空闲时）> MMIO/cbo.zero 写回（store 流水 0 空闲时）
  //   > store 流水 0。后端的 store 写回恒接收。
  logic other_wins, smb_slot_free, smb_wins;
  assign other_wins    = otherStout_out_valid & ~stu0_stout_valid;
  assign smb_slot_free = ~otherStout_out_valid & ~stu0_stout_valid & ~stu0_vecstout_valid & ~stu1_vecstout_valid;
  assign smb_wins      = smb_writeBack_valid & smb_slot_free;
  assign io_mem_to_ooo_writebackSta_0_valid = smb_wins | other_wins | stu0_stout_valid;
  assign wbSta0 = smb_wins ? wbSta0_smb : other_wins ? wbSta0_other : wbSta0_stu;
  assign smb_writeBack_ready  = smb_slot_free;
  assign smb_storeVecOutValid = stu0_vecstout_valid | stu1_vecstout_valid;
  assign otherStout_out_ready    = other_wins;
  assign otherStout_rightOutFire = other_wins & otherStout_out_valid;

  // 向量写回口 0：segment > 向量 load 合并 0 > 向量 store 合并 0（PriorityMux）
  assign io_mem_to_ooo_writebackVldu_0_valid = vlMerge_uopWriteback_0_valid | vsMerge0_uopWriteback_0_valid
                                             | vSeg_uopwriteback_valid;
  assign wbVldu0 = vSeg_uopwriteback_valid ? wbVldu0_seg : vlMerge_uopWriteback_0_valid ? wbVldu0_vl : wbVldu0_vs;
  assign vlMerge_uopWriteback_0_ready  = io_mem_to_ooo_writebackVldu_0_ready & ~vSeg_uopwriteback_valid;
  assign vsMerge0_uopWriteback_0_ready = io_mem_to_ooo_writebackVldu_0_ready & ~vlMerge_uopWriteback_0_valid
                                       & ~vSeg_uopwriteback_valid;
  // 向量写回口 1：fault-only-first 改 vl 的写回 > 向量 load 合并 1 > 向量 store 合并 1
  assign io_mem_to_ooo_writebackVldu_1_valid = vlMerge_uopWriteback_1_valid | vsMerge1_uopWriteback_0_valid
                                             | vfof_uopWriteback_valid;
  assign wbVldu1 = vfof_uopWriteback_valid ? wbVldu1_vfof : vlMerge_uopWriteback_1_valid ? wbVldu1_vl : wbVldu1_vs;
  assign vlMerge_uopWriteback_1_ready  = io_mem_to_ooo_writebackVldu_1_ready & ~vfof_uopWriteback_valid;
  assign vsMerge1_uopWriteback_0_ready = io_mem_to_ooo_writebackVldu_1_ready & ~vlMerge_uopWriteback_1_valid
                                       & ~vfof_uopWriteback_valid;
  // 向量 store 发射队列 0 的慢反馈：segment 与 store 合并缓冲 0 独热合一
  assign vstuFb0 = ({VSTUFB0_W{vSeg_feedback_valid}} & vstuFb0_seg)
                 | ({VSTUFB0_W{vsMerge0_feedback_0_valid}} & vstuFb0_vs);

  // merge 缓冲的流水入口：标量流水的向量结果优先，否则非对齐缓冲拆出来的元素
  assign ldu1VecWb_valid   = ldu1_vecldout_valid ? ldu1_vecldout_valid : lmb_vecWriteBack_valid;
  assign ldu1VecWb_mBIndex = ldu1_vecldout_valid ? ldu1_vecldout_bits_mBIndex : lmb_vecWriteBack_bits_mBIndex;
  assign vlMergeIn1 = ldu1_vecldout_valid ? vlMergeIn1_ldu : vlMergeIn1_lmb;
  assign vsMergeIn0 = stu0_vecstout_valid ? vsMergeIn0_stu : vsMergeIn0_smb;
  assign vsMergeIn1 = stu1_vecstout_valid ? vsMergeIn1_stu : vsMergeIn1_smb;

  // ===========================================================================
  // §9 向量发射分流
  //   向量访存发射口 i 上的 uop 按 fuOpType[8:7] 分给 vlSplit（01 = load）或 vsSplit（10 = store）；
  //   口 0 上若是 segment 指令（fuType 第 33 / 34 位 = vsegldu / vsegstu），整条交给 VSegmentUnit，两个 split 都不收。
  //   fault-only-first 的最后一个 uop（isVleff && lastUop）不进 vlSplit（由 VfofBuffer 处理）。
  // ===========================================================================
  logic vLoadCanAccept_0, vLoadCanAccept_1, vStoreCanAccept_0, vStoreCanAccept_1;
  assign segment_issue_valid = io_ooo_to_mem_issueVldu_0_valid
                             & (io_ooo_to_mem_issueVldu_0_bits_uop_fuType[33] | io_ooo_to_mem_issueVldu_0_bits_uop_fuType[34]);
  assign vLoadCanAccept_0  = vlSplit0_in_ready & (io_ooo_to_mem_issueVldu_0_bits_uop_fuOpType[8:7] == 2'b01);
  assign vLoadCanAccept_1  = vlSplit1_in_ready & (io_ooo_to_mem_issueVldu_1_bits_uop_fuOpType[8:7] == 2'b01);
  assign vStoreCanAccept_0 = vsSplit0_in_ready & (io_ooo_to_mem_issueVldu_0_bits_uop_fuOpType[8:7] == 2'b10);
  assign vStoreCanAccept_1 = vsSplit1_in_ready & (io_ooo_to_mem_issueVldu_1_bits_uop_fuOpType[8:7] == 2'b10);
  assign vlSplit0_in_valid = io_ooo_to_mem_issueVldu_0_valid & vLoadCanAccept_0 & ~segment_issue_valid
                           & ~(io_ooo_to_mem_issueVldu_0_bits_uop_vpu_isVleff & io_ooo_to_mem_issueVldu_0_bits_uop_vpu_lastUop
                               & io_ooo_to_mem_issueVldu_0_valid);
  assign vlSplit1_in_valid = io_ooo_to_mem_issueVldu_1_valid & vLoadCanAccept_1 & ~segment_issue_valid
                           & ~(io_ooo_to_mem_issueVldu_1_bits_uop_vpu_isVleff & io_ooo_to_mem_issueVldu_1_bits_uop_vpu_lastUop
                               & io_ooo_to_mem_issueVldu_1_valid);
  assign vsSplit0_in_valid = io_ooo_to_mem_issueVldu_0_valid & vStoreCanAccept_0 & ~segment_issue_valid;
  assign vsSplit1_in_valid = io_ooo_to_mem_issueVldu_1_valid & vStoreCanAccept_1 & ~segment_issue_valid;
  assign io_ooo_to_mem_issueVldu_0_ready = vLoadCanAccept_0 | vStoreCanAccept_0 | segment_issue_valid;
  assign io_ooo_to_mem_issueVldu_1_ready = vLoadCanAccept_1 | vStoreCanAccept_1;

  // split → 标量流水之间的打拍级（NewPipelineConnect）：这一拍若有新 uop 进来（左侧 fire），看新 uop 要不要被冲刷，
  //   否则看级里那条；冲刷判据 = robIdx.needFlush(io.redirect)（本拍、未打拍的重定向）。
  //   （纯函数：重定向也作为参数传入 —— 函数体里直接读模块信号的话，连续赋值只对实参敏感，仿真会漏更新）
  function automatic logic need_flush(input logic flag, input logic [7:0] value,
                                      input logic rd_valid, input logic rd_level,
                                      input logic rd_flag, input logic [7:0] rd_value);
    // isAfter(uop, redirect) || (redirect.level == flushItself && uop == redirect)
    return rd_valid & ((rd_level & ({flag, value} == {rd_flag, rd_value})) | (flag ^ rd_flag ^ (value > rd_value)));
  endfunction
  logic vlSplit0_flush, vlSplit1_flush, vsSplit0_flush, vsSplit1_flush;     // 刚出 split 的那条要不要冲刷
  logic vlToLdu0_flush, vlToLdu1_flush, vsToStu0_flush, vsToStu1_flush;     // 打拍级里那条要不要冲刷
  assign vlSplit0_flush = need_flush(vlSplit0_out_bits_uop_robIdx_flag, vlSplit0_out_bits_uop_robIdx_value,
                                     io_redirect_valid, io_redirect_bits_level, io_redirect_bits_robIdx_flag,
                                     io_redirect_bits_robIdx_value);
  assign vlSplit1_flush = need_flush(vlSplit1_out_bits_uop_robIdx_flag, vlSplit1_out_bits_uop_robIdx_value,
                                     io_redirect_valid, io_redirect_bits_level, io_redirect_bits_robIdx_flag,
                                     io_redirect_bits_robIdx_value);
  assign vsSplit0_flush = need_flush(vsSplit0_out_bits_uop_robIdx_flag, vsSplit0_out_bits_uop_robIdx_value,
                                     io_redirect_valid, io_redirect_bits_level, io_redirect_bits_robIdx_flag,
                                     io_redirect_bits_robIdx_value);
  assign vsSplit1_flush = need_flush(vsSplit1_out_bits_uop_robIdx_flag, vsSplit1_out_bits_uop_robIdx_value,
                                     io_redirect_valid, io_redirect_bits_level, io_redirect_bits_robIdx_flag,
                                     io_redirect_bits_robIdx_value);
  assign vlToLdu0_flush = need_flush(vlToLdu0_out_bits_uop_robIdx_flag, vlToLdu0_out_bits_uop_robIdx_value,
                                     io_redirect_valid, io_redirect_bits_level, io_redirect_bits_robIdx_flag,
                                     io_redirect_bits_robIdx_value);
  assign vlToLdu1_flush = need_flush(vlToLdu1_out_bits_uop_robIdx_flag, vlToLdu1_out_bits_uop_robIdx_value,
                                     io_redirect_valid, io_redirect_bits_level, io_redirect_bits_robIdx_flag,
                                     io_redirect_bits_robIdx_value);
  assign vsToStu0_flush = need_flush(vsToStu0_out_bits_uop_robIdx_flag, vsToStu0_out_bits_uop_robIdx_value,
                                     io_redirect_valid, io_redirect_bits_level, io_redirect_bits_robIdx_flag,
                                     io_redirect_bits_robIdx_value);
  assign vsToStu1_flush = need_flush(vsToStu1_out_bits_uop_robIdx_flag, vsToStu1_out_bits_uop_robIdx_value,
                                     io_redirect_valid, io_redirect_bits_level, io_redirect_bits_robIdx_flag,
                                     io_redirect_bits_robIdx_value);
  assign vlToLdu0_isFlush = (vlToLdu0_in_ready & vlSplit0_out_valid) ? vlSplit0_flush : vlToLdu0_flush;
  assign vlToLdu1_isFlush = (vlToLdu1_in_ready & vlSplit1_out_valid) ? vlSplit1_flush : vlToLdu1_flush;
  assign vsToStu0_isFlush = (vsToStu0_in_ready & vsSplit0_out_valid) ? vsSplit0_flush : vsToStu0_flush;
  assign vsToStu1_isFlush = (vsToStu1_in_ready & vsSplit1_out_valid) ? vsSplit1_flush : vsToStu1_flush;
  assign vlToLdu0_rightOutFire = ldu0_vecldin_ready & vlToLdu0_out_valid;
  assign vlToLdu1_rightOutFire = ldu1_vecldin_ready & vlToLdu1_out_valid;
  assign vsToStu0_rightOutFire = stu0_vecstin_ready & vsToStu0_out_valid;
  assign vsToStu1_rightOutFire = stu1_vecstin_ready & vsToStu1_out_valid;

  // StoreQueue 的 MMIO / cbo.zero store 写回先过一级打拍（otherStoutConnect）：cbo.zero 优先（两者不会同时有）
  assign otherStout_in_valid = lsq_mmioStout_valid | lsq_cboZeroStout_valid;
  assign otherStoutIn = lsq_cboZeroStout_valid ? otherStoutIn_cbo : otherStoutIn_mmio;

  // ===========================================================================
  // §10 Sbuffer
  //   写入口 0 由 StoreQueue 出队口 0 与 segment 单元独热合一（segment 的 store 不经 StoreQueue）；
  //   difftest 信息同理（segment 写入时报它自己的 uop 与数据）。
  //   冲刷：fence / 原子 / segment / cbo 任一要求冲刷就打一拍发给 Sbuffer（与 Uncache 共用同一个冲刷 valid）；
  //   Sbuffer 与 Uncache 都空了即"store 通路已空"，打一拍报给后端（sbIsEmpty）。
  // ===========================================================================
  assign sbufIn0 = ({SBUFIN0_W{vSeg_sbuffer_valid}} & sbufIn0_seg) | ({SBUFIN0_W{lsq_sbuffer_0_valid}} & sbufIn0_lsq);
  assign sbuffer_diffStore_diffInfo_0_uop_fuType   = vSeg_sbuffer_valid ? vSeg_vecDifftestInfo_bits_uop_fuType
                                                                        : lsq_diffStore_diffInfo_0_uop_fuType;
  assign sbuffer_diffStore_diffInfo_0_uop_fuOpType = vSeg_sbuffer_valid ? vSeg_vecDifftestInfo_bits_uop_fuOpType
                                                                        : lsq_diffStore_diffInfo_0_uop_fuOpType;
  assign sbuffer_diffStore_diffInfo_0_uop_vpu_nf   = vSeg_sbuffer_valid ? vSeg_vecDifftestInfo_bits_uop_vpu_nf
                                                                        : lsq_diffStore_diffInfo_0_uop_vpu_nf;
  assign sbuffer_diffStore_diffInfo_0_uop_vpu_veew = vSeg_sbuffer_valid ? vSeg_vecDifftestInfo_bits_uop_vpu_veew
                                                                        : lsq_diffStore_diffInfo_0_uop_vpu_veew;
  assign sbuffer_diffStore_diffInfo_0_uop_robIdx_value = vSeg_sbuffer_valid ? vSeg_vecDifftestInfo_bits_uop_robIdx_value
                                                                            : lsq_diffStore_diffInfo_0_uop_robIdx_value;
  assign sbuffer_diffStore_diffInfo_0_offset       = vSeg_sbuffer_valid ? 6'b0 : lsq_diffStore_diffInfo_0_offset;
  assign sbuffer_diffStore_pmaStore_0_valid        = vSeg_sbuffer_valid ? (sbuffer_in_0_ready & vSeg_sbuffer_valid)
                                                                        : lsq_diffStore_pmaStore_0_valid;
  assign sbuffer_diffStore_pmaStore_0_bits_data    = vSeg_sbuffer_valid ? vSeg_sbuffer_bits_data
                                                                        : lsq_diffStore_pmaStore_0_bits_data;
  assign sbuffer_diffStore_pmaStore_0_bits_mask    = vSeg_sbuffer_valid ? vSeg_sbuffer_bits_mask
                                                                        : lsq_diffStore_pmaStore_0_bits_mask;
  assign sbuffer_diffStore_pmaStore_0_bits_addr    = vSeg_sbuffer_valid ? vSeg_sbuffer_bits_addr
                                                                        : lsq_diffStore_pmaStore_0_bits_addr;
  assign sbuffer_diffStore_pmaStore_0_bits_wline   = vSeg_sbuffer_valid ? 1'b0 : lsq_diffStore_pmaStore_0_bits_wline;
  assign sbuffer_diffStore_pmaStore_0_bits_vecValid = vSeg_sbuffer_valid ? vSeg_sbuffer_bits_vecValid
                                                                         : lsq_diffStore_pmaStore_0_bits_vecValid;
  always_ff @(posedge clock) begin
    sb_flush_valid <= io_ooo_to_mem_flushSb | amo_flush_sbuffer_valid | vSeg_flush_sbuffer_valid | lsq_flushSbuffer_valid;
  end
  assign store_path_empty = sbuffer_flush_empty & uncache_flush_empty;
  always_ff @(posedge clock) begin
    sb_empty_q <= store_path_empty;
  end

  // ===========================================================================
  // §11 Uncache：LSQ 的 uncache 请求经一级打拍（uncacheReqReg）进 Uncache，回应经一级打拍（uncacheRespReg）回 LSQ。
  //   状态机（异步复位到空闲）：
  //     空闲 —— 请求被接收时：标量请求若不是"可乱序发出的 NC 写"（!nc || !outstanding_enable）进入"标量 uncache 中"；
  //             （非 LSQ 来源的请求在本配置下不存在，按 Chisel 留着"向量 uncache 中"分支）
  //     标量 / 向量 uncache 中 —— 回应被接收时回到空闲。
  //   回应 / idResp 何时送给 LSQ：开了 outstanding（允许多个在途）时随时；否则只在"标量 uncache 中"。
  // ===========================================================================
  localparam logic [1:0] UNC_IDLE = 2'd0, UNC_SCALAR = 2'd1, UNC_VECTOR = 2'd2;
  logic [1:0] uncache_state;
  logic       uncache_req_fire, uncache_resp_to_lsq;
  assign lsq_uncache_req_ready = lsq_uncache_req_valid & uncacheReqReg_in_ready;
  assign uncache_req_fire      = uncacheReqReg_in_ready & lsq_uncache_req_valid;
  assign uncache_resp_to_lsq   = io_ooo_to_mem_csrCtrl_uncache_write_outstanding_enable | (uncache_state == UNC_SCALAR);
  assign uncacheRespReg_out_ready = uncache_resp_to_lsq;
  assign lsq_uncache_resp_valid   = uncache_resp_to_lsq & uncacheRespReg_out_valid;
  assign lsq_uncache_idResp_valid = uncache_resp_to_lsq & uncache_lsq_idResp_valid;
  always_ff @(posedge clock or posedge reset) begin
    if (reset) uncache_state <= UNC_IDLE;
    else begin
      unique case (uncache_state)
        UNC_IDLE:
          if (uncache_req_fire) begin
            if (lsq_uncache_req_valid) begin
              if (!lsq_uncache_req_bits_nc || !io_ooo_to_mem_csrCtrl_uncache_write_outstanding_enable)
                uncache_state <= UNC_SCALAR;
            end else if (!io_ooo_to_mem_csrCtrl_uncache_write_outstanding_enable) begin
              uncache_state <= UNC_VECTOR;
            end
          end
        UNC_SCALAR, UNC_VECTOR:
          if (uncache_resp_to_lsq & uncacheRespReg_out_valid) uncache_state <= UNC_IDLE;
        default: ;
      endcase
    end
  end

  // ===========================================================================
  // §12 访存违例回滚：3 条 load 流水的 rollback、LoadQueue 的 nack 回滚、2 个 nuke（st-ld 违例）回滚，
  //   挑 ROB 序最老的一个（selectOldestRedirect）。older(j,i) = isAfter(rob_j, rob_i)，即源 i 比源 j 更老；
  //   源 i 被选中 ⇔ 自己有效，且每个别的源 j 要么无效、要么比 i 新（j<i 时要求 isAfter(j,i)，j>i 时要求 !isAfter(i,j)）。
  // ===========================================================================
  logic       rb_valid [6];
  logic       rb_flag  [6];
  logic [7:0] rb_value [6];
  assign rb_valid[0] = ldu0_rollback_valid;        assign rb_flag[0] = ldu0_rollback_bits_robIdx_flag;
  assign rb_valid[1] = ldu1_rollback_valid;        assign rb_flag[1] = ldu1_rollback_bits_robIdx_flag;
  assign rb_valid[2] = ldu2_rollback_valid;        assign rb_flag[2] = ldu2_rollback_bits_robIdx_flag;
  assign rb_valid[3] = lsq_nack_rollback_0_valid;  assign rb_flag[3] = lsq_nack_rollback_0_bits_robIdx_flag;
  assign rb_valid[4] = lsq_nuke_rollback_0_valid;  assign rb_flag[4] = lsq_nuke_rollback_0_bits_robIdx_flag;
  assign rb_valid[5] = lsq_nuke_rollback_1_valid;  assign rb_flag[5] = lsq_nuke_rollback_1_bits_robIdx_flag;
  assign rb_value[0] = ldu0_rollback_bits_robIdx_value;
  assign rb_value[1] = ldu1_rollback_bits_robIdx_value;
  assign rb_value[2] = ldu2_rollback_bits_robIdx_value;
  assign rb_value[3] = lsq_nack_rollback_0_bits_robIdx_value;
  assign rb_value[4] = lsq_nuke_rollback_0_bits_robIdx_value;
  assign rb_value[5] = lsq_nuke_rollback_1_bits_robIdx_value;
  function automatic logic rob_is_after(input logic fa, input logic [7:0] va, input logic fb, input logic [7:0] vb);
    return fa ^ fb ^ (va > vb);    // 环形 ROB 指针：a 在 b 之后
  endfunction
  logic rb_oldest [6];
  always_comb begin
    for (int i = 0; i < 6; i++) begin
      rb_oldest[i] = rb_valid[i];
      for (int j = 0; j < 6; j++) begin
        if (j < i)      rb_oldest[i] &= ~rb_valid[j] |  rob_is_after(rb_flag[j], rb_value[j], rb_flag[i], rb_value[i]);
        else if (j > i) rb_oldest[i] &= ~rb_valid[j] | ~rob_is_after(rb_flag[i], rb_value[i], rb_flag[j], rb_value[j]);
      end
    end
  end
  assign memVio = ({MEMVIO_W{rb_oldest[0]}} & memVio_ldu0) | ({MEMVIO_W{rb_oldest[1]}} & memVio_ldu1)
                | ({MEMVIO_W{rb_oldest[2]}} & memVio_ldu2) | ({MEMVIO_W{rb_oldest[3]}} & memVio_nack)
                | ({MEMVIO_W{rb_oldest[4]}} & memVio_nuke0) | ({MEMVIO_W{rb_oldest[5]}} & memVio_nuke1);

  // ===========================================================================
  // §13 硬件预取
  //   训练 PC：load 发射那拍的 pc 打一拍（s1），再按 load 流水报的 s1/s2 推测有效信号逐级 RegEnable；
  //   指针追逐（s2_ptr_chasing）的 load 跳过一级，用 s1 的 pc 直接在 s2 采（chase）。L1 流预取与 SMS 各有一套。
  //   SMS 训练：全部 load（train_on_hit 时）或首次发射且缺失的 load；L1 流预取：首次发射的 load，
  //   其中缺失或"由 stride 预取带进来的"（meta_prefetch = 2）也训练 stride 部分。
  // ===========================================================================
  logic [49:0] issue_pc [3];
  logic        s1_spec [3], s2_spec [3], s1_spec_l1 [3], s2_spec_l1 [3], ptr_chasing [3];
  assign issue_pc[0] = io_ooo_to_mem_issueLda_0_bits_uop_pc;
  assign issue_pc[1] = io_ooo_to_mem_issueLda_1_bits_uop_pc;
  assign issue_pc[2] = io_ooo_to_mem_issueLda_2_bits_uop_pc;
  assign s1_spec[0] = ldu0_s1_prefetch_spec;  assign s2_spec[0] = ldu0_s2_prefetch_spec;
  assign s1_spec[1] = ldu1_s1_prefetch_spec;  assign s2_spec[1] = ldu1_s2_prefetch_spec;
  assign s1_spec[2] = ldu2_s1_prefetch_spec;  assign s2_spec[2] = ldu2_s2_prefetch_spec;
  assign s1_spec_l1[0] = ldu0_s1_prefetch_spec_l1;  assign s2_spec_l1[0] = ldu0_s2_prefetch_spec_l1;
  assign s1_spec_l1[1] = ldu1_s1_prefetch_spec_l1;  assign s2_spec_l1[1] = ldu1_s2_prefetch_spec_l1;
  assign s1_spec_l1[2] = ldu2_s1_prefetch_spec_l1;  assign s2_spec_l1[2] = ldu2_s2_prefetch_spec_l1;
  assign ptr_chasing[0] = ldu0_s2_ptr_chasing;
  assign ptr_chasing[1] = ldu1_s2_ptr_chasing;
  assign ptr_chasing[2] = ldu2_s2_ptr_chasing;
  logic [49:0] l1pfPc_s1 [3], l1pfPc_s2 [3], l1pfPc_s3 [3], l1pfPc_chase [3];
  logic [49:0] smsPc_s1 [3],  smsPc_s2 [3],  smsPc_s3 [3],  smsPc_chase [3];
  always_ff @(posedge clock) begin
    for (int i = 0; i < 3; i++) begin
      l1pfPc_s1[i] <= issue_pc[i];
      if (s2_spec_l1[i]) begin
        l1pfPc_chase[i] <= l1pfPc_s1[i];
        l1pfPc_s3[i]    <= l1pfPc_s2[i];
      end
      if (s1_spec_l1[i]) l1pfPc_s2[i] <= l1pfPc_s1[i];
      smsPc_s1[i] <= issue_pc[i];
      if (s2_spec[i]) begin
        smsPc_chase[i] <= smsPc_s1[i];
        smsPc_s3[i]    <= smsPc_s2[i];
      end
      if (s1_spec[i]) smsPc_s2[i] <= smsPc_s1[i];
    end
  end
  assign sms_ld_in_0_valid = (pf_train_on_hit[1] | (ldu0_prefetch_train_bits_isFirstIssue & ldu0_prefetch_train_bits_miss))
                           & ldu0_prefetch_train_valid;
  assign sms_ld_in_1_valid = (pf_train_on_hit[1] | (ldu1_prefetch_train_bits_isFirstIssue & ldu1_prefetch_train_bits_miss))
                           & ldu1_prefetch_train_valid;
  assign sms_ld_in_2_valid = (pf_train_on_hit[1] | (ldu2_prefetch_train_bits_isFirstIssue & ldu2_prefetch_train_bits_miss))
                           & ldu2_prefetch_train_valid;
  assign sms_ld_in_0_bits_uop_pc = ptr_chasing[0] ? smsPc_chase[0] : smsPc_s3[0];
  assign sms_ld_in_1_bits_uop_pc = ptr_chasing[1] ? smsPc_chase[1] : smsPc_s3[1];
  assign sms_ld_in_2_bits_uop_pc = ptr_chasing[2] ? smsPc_chase[2] : smsPc_s3[2];
  localparam logic [2:0] PF_SRC_STRIDE = 3'd2;     // L1PfSourceParameter：stride 预取带进来的块
  assign l1Pf_ld_in_0_valid = ldu0_prefetch_train_l1_valid & ldu0_prefetch_train_l1_bits_isFirstIssue;
  assign l1Pf_ld_in_1_valid = ldu1_prefetch_train_l1_valid & ldu1_prefetch_train_l1_bits_isFirstIssue;
  assign l1Pf_ld_in_2_valid = ldu2_prefetch_train_l1_valid & ldu2_prefetch_train_l1_bits_isFirstIssue;
  assign l1Pf_stride_train_0_valid = l1Pf_ld_in_0_valid
                                   & (ldu0_prefetch_train_l1_bits_miss | ldu0_prefetch_train_l1_bits_meta_prefetch == PF_SRC_STRIDE);
  assign l1Pf_stride_train_1_valid = l1Pf_ld_in_1_valid
                                   & (ldu1_prefetch_train_l1_bits_miss | ldu1_prefetch_train_l1_bits_meta_prefetch == PF_SRC_STRIDE);
  assign l1Pf_stride_train_2_valid = l1Pf_ld_in_2_valid
                                   & (ldu2_prefetch_train_l1_bits_miss | ldu2_prefetch_train_l1_bits_meta_prefetch == PF_SRC_STRIDE);
  assign l1Pf_stride_train_0_bits_uop_pc = ptr_chasing[0] ? l1pfPc_chase[0] : l1pfPc_s3[0];
  assign l1Pf_stride_train_1_bits_uop_pc = ptr_chasing[1] ? l1pfPc_chase[1] : l1pfPc_s3[1];
  assign l1Pf_stride_train_2_bits_uop_pc = ptr_chasing[2] ? l1pfPc_chase[2] : l1pfPc_s3[2];

  // L1 预取请求（L1 流预取经一级打拍后）同时送三条 load 流水；load 流水 1/2 只收低置信度请求，
  //   流水 0 按请求的置信度看对应的 canAccept。原子指令执行期间不发。
  assign l1PfReqQueue_out_ready = (l1PfReqQueue_out_bits_confidence ? ldu0_canAcceptHighConfPrefetch
                                                                    : ldu0_canAcceptLowConfPrefetch)
                                | ldu1_canAcceptLowConfPrefetch | ldu2_canAcceptLowConfPrefetch;
  assign l1PfReq_valid = ~amo_active & l1PfReqQueue_out_valid;

  // 向 L2 发预取：SMS 与 L1 流预取各延迟两拍，L1 流预取优先
  assign auto_inner_l2_pf_sender_out_addr_valid = smsToL2Dly_out_valid | l1PfToL2Dly_out_valid;
  assign auto_inner_l2_pf_sender_out_addr = {16'b0, l1PfToL2Dly_out_valid ? l1PfToL2Dly_out_bits_addr
                                                                          : smsToL2Dly_out_bits_addr};
  assign auto_inner_l2_pf_sender_out_pf_source = l1PfToL2Dly_out_valid ? l1PfToL2Dly_out_bits_source
                                                                       : smsToL2Dly_out_bits_source;

  // 本层的两个性能事件：本拍 load / store 地址发射口上有几条（编号 142 / 143）
  logic [1:0] ld_deq_count, st_deq_count;
  assign ld_deq_count = 2'(io_ooo_to_mem_issueLda_0_valid) + 2'(io_ooo_to_mem_issueLda_1_valid)
                      + 2'(io_ooo_to_mem_issueLda_2_valid);
  assign st_deq_count = 2'(io_ooo_to_mem_issueSta_0_valid) + 2'(io_ooo_to_mem_issueSta_1_valid);
  assign perfHpm_events_sets_142_value = {4'b0, ld_deq_count};
  assign perfHpm_events_sets_143_value = {4'b0, st_deq_count};

  // ===========================================================================
  // §14 例外地址
  //   原子单元 / segment 单元报例外时把地址锁住（RegEnable），并置"挂起"位（异步复位 0）；重定向 10 拍后
  //   （DelayN(redirect.valid, 10)，两条延迟线）清掉挂起位。送给后端的 vaddr / gpaddr / 非叶 PTE 标志：
  //   原子 > segment > LSQ，再打一拍。vaddr 若需扩展（LSQ 报 vaNeedExt），按当前翻译模式做零 / 符号扩展：
  //     Bare（或 M 态）→ 取物理地址宽 48 位零扩展；Sv39 / Sv48 → 39 / 48 位符号扩展；
  //     Sv39x4 / Sv48x4（只有 G-stage）→ 41 / 50 位零扩展。
  // ===========================================================================
  logic        amo_exc_pending, seg_exc_pending;
  logic [63:0] amo_exc_vaddr, amo_exc_gpaddr, seg_exc_vaddr, seg_exc_gpaddr;
  logic        amo_exc_nonLeafPte, seg_exc_nonLeafPte;
  always_ff @(posedge clock or posedge reset) begin
    if (reset) begin
      amo_exc_pending <= 1'b0;
      seg_exc_pending <= 1'b0;
    end else begin
      if (amoExcClrDly_out && amo_exc_pending) amo_exc_pending <= 1'b0;
      else if (amo_exceptionInfo_valid)        amo_exc_pending <= 1'b1;
      if (vsegExcClrDly_out && seg_exc_pending) seg_exc_pending <= 1'b0;
      else if (vSeg_exceptionInfo_valid)        seg_exc_pending <= 1'b1;
    end
  end
  always_ff @(posedge clock) begin
    if (amo_exceptionInfo_valid) begin
      amo_exc_vaddr      <= amo_exceptionInfo_bits_vaddr;
      amo_exc_gpaddr     <= amo_exceptionInfo_bits_gpaddr;
      amo_exc_nonLeafPte <= amo_exceptionInfo_bits_isForVSnonLeafPTE;
    end
    if (vSeg_exceptionInfo_valid) begin
      seg_exc_vaddr      <= vSeg_exceptionInfo_bits_vaddr;
      seg_exc_gpaddr     <= vSeg_exceptionInfo_bits_gpaddr;
      seg_exc_nonLeafPte <= vSeg_exceptionInfo_bits_isForVSnonLeafPTE;
    end
  end
  logic [63:0] exc_vaddr_raw, exc_vaddr_ext;
  logic        exc_va_need_ext, exc_is_virt;
  logic        use_bare, use_sv39, use_sv48, use_sv39x4, use_sv48x4;
  localparam logic [3:0] MODE_BARE = 4'd0, MODE_SV39 = 4'd8, MODE_SV48 = 4'd9;
  assign exc_vaddr_raw   = amo_exc_pending ? amo_exc_vaddr : seg_exc_pending ? seg_exc_vaddr : lsq_exceptionAddr_vaddr;
  assign exc_va_need_ext = ~amo_exc_pending & ~seg_exc_pending & lsq_exceptionAddr_vaNeedExt;
  assign exc_is_virt     = tlbcsr_priv_virt | (~amo_exc_pending & ~seg_exc_pending & lsq_exceptionAddr_isHyper);
  assign use_bare   = (exc_is_virt & tlbcsr_vsatp_mode == MODE_BARE & tlbcsr_hgatp_mode == MODE_BARE)
                    | (~exc_is_virt & tlbcsr_priv_dmode == 2'd3)
                    | (~exc_is_virt & tlbcsr_priv_dmode != 2'd3 & tlbcsr_satp_mode == MODE_BARE);
  assign use_sv39   = (exc_is_virt & tlbcsr_vsatp_mode == MODE_SV39)
                    | (~exc_is_virt & tlbcsr_priv_dmode != 2'd3 & tlbcsr_satp_mode == MODE_SV39);
  assign use_sv48   = (exc_is_virt & tlbcsr_vsatp_mode == MODE_SV48)
                    | (~exc_is_virt & tlbcsr_priv_dmode != 2'd3 & tlbcsr_satp_mode == MODE_SV48);
  assign use_sv39x4 = exc_is_virt & tlbcsr_vsatp_mode == MODE_BARE & tlbcsr_hgatp_mode == MODE_SV39;
  assign use_sv48x4 = exc_is_virt & tlbcsr_vsatp_mode == MODE_BARE & tlbcsr_hgatp_mode == MODE_SV48;
  assign exc_vaddr_ext = ({64{use_bare}}   & {16'b0, exc_vaddr_raw[47:0]})
                       | ({64{use_sv39}}   & {{25{exc_vaddr_raw[38]}}, exc_vaddr_raw[38:0]})
                       | ({64{use_sv48}}   & {{16{exc_vaddr_raw[47]}}, exc_vaddr_raw[47:0]})
                       | ({64{use_sv39x4}} & {23'b0, exc_vaddr_raw[40:0]})
                       | ({64{use_sv48x4}} & {14'b0, exc_vaddr_raw[49:0]});
  always_ff @(posedge clock) begin
    exc_vaddr_q      <= exc_va_need_ext ? exc_vaddr_ext : exc_vaddr_raw;
    exc_gpaddr_q     <= amo_exc_pending ? amo_exc_gpaddr : seg_exc_pending ? seg_exc_gpaddr : lsq_exceptionAddr_gpaddr;
    exc_nonLeafPte_q <= amo_exc_pending ? amo_exc_nonLeafPte
                      : seg_exc_pending ? seg_exc_nonLeafPte : lsq_exceptionAddr_isForVSnonLeafPTE;
  end

  // ===========================================================================
  // §15 顶层旁路（MemBlock 是 SoC 与核之间信号的必经之处，这些多半只是打一拍）
  // ===========================================================================
  // 中断与 L2 冲刷完成：打一拍送后端。nmi_31 = NMI 输入 0 或 BEU 本地中断
  always_ff @(posedge clock) begin
    l2_flush_done_q <= io_l2_flush_done;
    irq_msip_q      <= auto_inner_clint_int_sink_in_0;
    irq_mtip_q      <= auto_inner_clint_int_sink_in_1;
    irq_meip_q      <= auto_inner_plic_int_sink_in_0_0;
    irq_seip_q      <= auto_inner_plic_int_sink_in_1_0;
    irq_debug_q     <= auto_inner_debug_int_sink_in_0;
    irq_nmi31_q     <= auto_inner_nmi_int_sink_in_0 | auto_inner_beu_local_int_sink_in_0;
    irq_nmi43_q     <= auto_inner_nmi_int_sink_in_1;
  end
  // 复位向量、cpu 停机 / 致命错误、ICache 的 BEU 错误：打一拍（致命错误异步复位 0）
  always_ff @(posedge clock) begin
    reset_vector_q     <= io_outer_reset_vector;
    cpu_halt_q         <= io_ooo_to_mem_backendToTopBypass_cpuHalted;
    beu_icache_valid_q <= io_inner_beu_errors_icache_ecc_error_valid;
    beu_icache_bits_q  <= io_inner_beu_errors_icache_ecc_error_bits;
  end
  always_ff @(posedge clock or posedge reset) begin
    if (reset) cpu_critical_error_q <= 1'b0;
    else       cpu_critical_error_q <= io_ooo_to_mem_backendToTopBypass_cpuCriticalError;
  end
  // L2 的 hc 性能事件：69 路打一拍转给后端（第 0 路的输入在本配置下恒 0）
  always_ff @(posedge clock) begin
    hc_perf_q[0]  <= 6'b0;
    hc_perf_q[1]  <= io_outer_hc_perfEvents_1_value;
    hc_perf_q[2]  <= io_outer_hc_perfEvents_2_value;
    hc_perf_q[3]  <= io_outer_hc_perfEvents_3_value;
    hc_perf_q[4]  <= io_outer_hc_perfEvents_4_value;
    hc_perf_q[5]  <= io_outer_hc_perfEvents_5_value;
    hc_perf_q[6]  <= io_outer_hc_perfEvents_6_value;
    hc_perf_q[7]  <= io_outer_hc_perfEvents_7_value;
    hc_perf_q[8]  <= io_outer_hc_perfEvents_8_value;
    hc_perf_q[9]  <= io_outer_hc_perfEvents_9_value;
    hc_perf_q[10] <= io_outer_hc_perfEvents_10_value;
    hc_perf_q[11] <= io_outer_hc_perfEvents_11_value;
    hc_perf_q[12] <= io_outer_hc_perfEvents_12_value;
    hc_perf_q[13] <= io_outer_hc_perfEvents_13_value;
    hc_perf_q[14] <= io_outer_hc_perfEvents_14_value;
    hc_perf_q[15] <= io_outer_hc_perfEvents_15_value;
    hc_perf_q[16] <= io_outer_hc_perfEvents_16_value;
    hc_perf_q[17] <= io_outer_hc_perfEvents_17_value;
    hc_perf_q[18] <= io_outer_hc_perfEvents_18_value;
    hc_perf_q[19] <= io_outer_hc_perfEvents_19_value;
    hc_perf_q[20] <= io_outer_hc_perfEvents_20_value;
    hc_perf_q[21] <= io_outer_hc_perfEvents_21_value;
    hc_perf_q[22] <= io_outer_hc_perfEvents_22_value;
    hc_perf_q[23] <= io_outer_hc_perfEvents_23_value;
    hc_perf_q[24] <= io_outer_hc_perfEvents_24_value;
    hc_perf_q[25] <= io_outer_hc_perfEvents_25_value;
    hc_perf_q[26] <= io_outer_hc_perfEvents_26_value;
    hc_perf_q[27] <= io_outer_hc_perfEvents_27_value;
    hc_perf_q[28] <= io_outer_hc_perfEvents_28_value;
    hc_perf_q[29] <= io_outer_hc_perfEvents_29_value;
    hc_perf_q[30] <= io_outer_hc_perfEvents_30_value;
    hc_perf_q[31] <= io_outer_hc_perfEvents_31_value;
    hc_perf_q[32] <= io_outer_hc_perfEvents_32_value;
    hc_perf_q[33] <= io_outer_hc_perfEvents_33_value;
    hc_perf_q[34] <= io_outer_hc_perfEvents_34_value;
    hc_perf_q[35] <= io_outer_hc_perfEvents_35_value;
    hc_perf_q[36] <= io_outer_hc_perfEvents_36_value;
    hc_perf_q[37] <= io_outer_hc_perfEvents_37_value;
    hc_perf_q[38] <= io_outer_hc_perfEvents_38_value;
    hc_perf_q[39] <= io_outer_hc_perfEvents_39_value;
    hc_perf_q[40] <= io_outer_hc_perfEvents_40_value;
    hc_perf_q[41] <= io_outer_hc_perfEvents_41_value;
    hc_perf_q[42] <= io_outer_hc_perfEvents_42_value;
    hc_perf_q[43] <= io_outer_hc_perfEvents_43_value;
    hc_perf_q[44] <= io_outer_hc_perfEvents_44_value;
    hc_perf_q[45] <= io_outer_hc_perfEvents_45_value;
    hc_perf_q[46] <= io_outer_hc_perfEvents_46_value;
    hc_perf_q[47] <= io_outer_hc_perfEvents_47_value;
    hc_perf_q[48] <= io_outer_hc_perfEvents_48_value;
    hc_perf_q[49] <= io_outer_hc_perfEvents_49_value;
    hc_perf_q[50] <= io_outer_hc_perfEvents_50_value;
    hc_perf_q[51] <= io_outer_hc_perfEvents_51_value;
    hc_perf_q[52] <= io_outer_hc_perfEvents_52_value;
    hc_perf_q[53] <= io_outer_hc_perfEvents_53_value;
    hc_perf_q[54] <= io_outer_hc_perfEvents_54_value;
    hc_perf_q[55] <= io_outer_hc_perfEvents_55_value;
    hc_perf_q[56] <= io_outer_hc_perfEvents_56_value;
    hc_perf_q[57] <= io_outer_hc_perfEvents_57_value;
    hc_perf_q[58] <= io_outer_hc_perfEvents_58_value;
    hc_perf_q[59] <= io_outer_hc_perfEvents_59_value;
    hc_perf_q[60] <= io_outer_hc_perfEvents_60_value;
    hc_perf_q[61] <= io_outer_hc_perfEvents_61_value;
    hc_perf_q[62] <= io_outer_hc_perfEvents_62_value;
    hc_perf_q[63] <= io_outer_hc_perfEvents_63_value;
    hc_perf_q[64] <= io_outer_hc_perfEvents_64_value;
    hc_perf_q[65] <= io_outer_hc_perfEvents_65_value;
    hc_perf_q[66] <= io_outer_hc_perfEvents_66_value;
    hc_perf_q[67] <= io_outer_hc_perfEvents_67_value;
    hc_perf_q[68] <= io_outer_hc_perfEvents_68_value;
  end

  // 处理器 trace 接口（后端 → L2Top 的 trace encoder）：打一拍；trap 只在第 0 组是 trap（itype 1 = 例外、2 = 中断）时
  //   采样，priv 与各组的 ilastsize / iaddr / ftqOffset 只在组 valid 时采样；送出的 iaddr = 块首地址 + ftqOffset×2。
  //   反方向 encoder → 后端的 enable / stall 也打一拍。组 valid 异步复位 0。
  logic [49:0] trace_grp_iaddr_q [3];
  logic [3:0]  trace_grp_ftqOffset_q [3];
  logic        tr_grp_valid [3];
  logic [6:0]  tr_grp_iretire [3];
  logic [3:0]  tr_grp_itype [3];
  logic        tr_grp_ilastsize [3];
  logic [49:0] tr_grp_iaddr [3];
  logic [3:0]  tr_grp_ftqOffset [3];
  assign tr_grp_valid[0]     = io_traceCoreInterfaceBypass_fromBackend_toEncoder_groups_0_valid;
  assign tr_grp_valid[1]     = io_traceCoreInterfaceBypass_fromBackend_toEncoder_groups_1_valid;
  assign tr_grp_valid[2]     = io_traceCoreInterfaceBypass_fromBackend_toEncoder_groups_2_valid;
  assign tr_grp_iretire[0]   = io_traceCoreInterfaceBypass_fromBackend_toEncoder_groups_0_bits_iretire;
  assign tr_grp_iretire[1]   = io_traceCoreInterfaceBypass_fromBackend_toEncoder_groups_1_bits_iretire;
  assign tr_grp_iretire[2]   = io_traceCoreInterfaceBypass_fromBackend_toEncoder_groups_2_bits_iretire;
  assign tr_grp_itype[0]     = io_traceCoreInterfaceBypass_fromBackend_toEncoder_groups_0_bits_itype;
  assign tr_grp_itype[1]     = io_traceCoreInterfaceBypass_fromBackend_toEncoder_groups_1_bits_itype;
  assign tr_grp_itype[2]     = io_traceCoreInterfaceBypass_fromBackend_toEncoder_groups_2_bits_itype;
  assign tr_grp_ilastsize[0] = io_traceCoreInterfaceBypass_fromBackend_toEncoder_groups_0_bits_ilastsize;
  assign tr_grp_ilastsize[1] = io_traceCoreInterfaceBypass_fromBackend_toEncoder_groups_1_bits_ilastsize;
  assign tr_grp_ilastsize[2] = io_traceCoreInterfaceBypass_fromBackend_toEncoder_groups_2_bits_ilastsize;
  assign tr_grp_iaddr[0]     = io_traceCoreInterfaceBypass_fromBackend_toEncoder_groups_0_bits_iaddr;
  assign tr_grp_iaddr[1]     = io_traceCoreInterfaceBypass_fromBackend_toEncoder_groups_1_bits_iaddr;
  assign tr_grp_iaddr[2]     = io_traceCoreInterfaceBypass_fromBackend_toEncoder_groups_2_bits_iaddr;
  assign tr_grp_ftqOffset[0] = io_traceCoreInterfaceBypass_fromBackend_toEncoder_groups_0_bits_ftqOffset;
  assign tr_grp_ftqOffset[1] = io_traceCoreInterfaceBypass_fromBackend_toEncoder_groups_1_bits_ftqOffset;
  assign tr_grp_ftqOffset[2] = io_traceCoreInterfaceBypass_fromBackend_toEncoder_groups_2_bits_ftqOffset;
  localparam logic [3:0] ITYPE_EXCEPTION = 4'd1, ITYPE_INTERRUPT = 4'd2;
  always_ff @(posedge clock) begin
    trace_enc_enable_q <= io_traceCoreInterfaceBypass_toL2Top_fromEncoder_enable;
    trace_enc_stall_q  <= io_traceCoreInterfaceBypass_toL2Top_fromEncoder_stall;
    if (tr_grp_valid[0] && (tr_grp_itype[0] == ITYPE_EXCEPTION || tr_grp_itype[0] == ITYPE_INTERRUPT)) begin
      trace_trap_cause_q <= io_traceCoreInterfaceBypass_fromBackend_toEncoder_trap_cause;
      trace_trap_tval_q  <= io_traceCoreInterfaceBypass_fromBackend_toEncoder_trap_tval;
    end
    if (tr_grp_valid[0]) trace_priv_q <= io_traceCoreInterfaceBypass_fromBackend_toEncoder_priv;
    trace_mstatus_q <= io_traceCoreInterfaceBypass_fromBackend_toEncoder_mstatus;
    for (int i = 0; i < 3; i++) begin
      trace_grp_iretire_q[i] <= tr_grp_iretire[i];
      trace_grp_itype_q[i]   <= tr_grp_itype[i];
      if (tr_grp_valid[i]) begin
        trace_grp_ilastsize_q[i] <= tr_grp_ilastsize[i];
        trace_grp_iaddr_q[i]     <= tr_grp_iaddr[i];
        trace_grp_ftqOffset_q[i] <= tr_grp_ftqOffset[i];
      end
    end
  end
  always_ff @(posedge clock or posedge reset) begin
    if (reset) for (int i = 0; i < 3; i++) trace_grp_valid_q[i] <= 1'b0;
    else       for (int i = 0; i < 3; i++) trace_grp_valid_q[i] <= tr_grp_valid[i];
  end
  assign io_traceCoreInterfaceBypass_toL2Top_toEncoder_groups_0_bits_iaddr = trace_grp_iaddr_q[0] + {45'b0, trace_grp_ftqOffset_q[0], 1'b0};
  assign io_traceCoreInterfaceBypass_toL2Top_toEncoder_groups_1_bits_iaddr = trace_grp_iaddr_q[1] + {45'b0, trace_grp_ftqOffset_q[1], 1'b0};
  assign io_traceCoreInterfaceBypass_toL2Top_toEncoder_groups_2_bits_iaddr = trace_grp_iaddr_q[2] + {45'b0, trace_grp_ftqOffset_q[2], 1'b0};

  // TopDown：L2 / L3 缺失打一拍送后端
  always_ff @(posedge clock) begin
    l2_miss_q <= io_topDownInfo_fromL2Top_l2Miss;
    l3_miss_q <= io_topDownInfo_fromL2Top_l3Miss;
  end

  // 本层的 8 路性能计数（HPerfMonitor 汇总后）打两拍送出
  logic [5:0] perf_d1 [8];
  logic [5:0] perf_now [8];
  assign perf_now[0] = perfHpm_perf_0_value;
  assign perf_now[1] = perfHpm_perf_1_value;
  assign perf_now[2] = perfHpm_perf_2_value;
  assign perf_now[3] = perfHpm_perf_3_value;
  assign perf_now[4] = perfHpm_perf_4_value;
  assign perf_now[5] = perfHpm_perf_5_value;
  assign perf_now[6] = perfHpm_perf_6_value;
  assign perf_now[7] = perfHpm_perf_7_value;
  always_ff @(posedge clock) begin
    for (int i = 0; i < 8; i++) begin
      perf_d1[i] <= perf_now[i];
      perf_d2[i] <= perf_d1[i];
    end
  end

  // ECC 错误上报（DCache / Uncache 各自延迟两拍后）：只在 CSR 打开 cache_error_enable 时报；DCache 的还要 report_to_beu
  assign io_dcacheError_ecc_error_valid  = csrCtrlDly_out_cache_error_enable & dcacheErrDly_out_valid
                                         & dcacheErrDly_out_bits_report_to_beu;
  assign io_uncacheError_ecc_error_valid = csrCtrlDly_out_cache_error_enable & uncacheErrDly_out_valid;

  // wfi：DCache、Uncache、LSQ、L2TLB 都没有在途访问才算安全
  assign io_wfi_wfiSafe = dcache_wfi_wfiSafe & uncache_wfi_wfiSafe & lsq_wfi_wfiSafe & ptw_wfi_wfiSafe;

endmodule

